import math

def add_vectors(v1, v2):
    x1, y1 = v1
    x2, y2 = v2
    return (x1 + x2, y1 + y2)

def dot_product(v1, v2):
    x1, y1 = v1
    x2, y2 = v2
    return x1 * x2 + y1 * y2

def scale_vector(v, factor):
    x, y = v
    return (x * factor, y * factor)

def subtract_vectors(v1, v2):
    negated = scale_vector(v2, -1.0)
    return add_vectors(v1, negated)

def magnitude(v):
    return math.sqrt(dot_product(v, v))

def normalize(v):
    length = magnitude(v)
    if length == 0.0:
        raise ValueError("cannot normalize the zero vector")
    return scale_vector(v, 1.0 / length)

def angle_between(v1, v2):
    denom = magnitude(v1) * magnitude(v2)
    if denom == 0.0:
        raise ValueError("angle undefined for the zero vector")
    cosine = dot_product(v1, v2) / denom
    cosine = min(cosine, 1.0)
    cosine = max(cosine, -1.0)
    return math.degrees(math.acos(cosine))

def format_vector(v, digits=3):
    x, y = v
    cell = "{0:." + str(digits) + "f}"
    return "(" + cell.format(x) + ", " + cell.format(y) + ")"

def describe(name, v):
    shape = format_vector(v)
    size = "|v|={0:.3f}".format(magnitude(v))
    return name + " " + shape + " " + size

def report(v1, v2):
    lines = []
    lines.append(describe("a =", v1))
    lines.append(describe("b =", v2))
    total = add_vectors(v1, v2)
    lines.append(describe("a+b =", total))
    diff = subtract_vectors(v1, v2)
    lines.append(describe("a-b =", diff))
    doubled = scale_vector(v1, 2.0)
    lines.append(describe("2a =", doubled))
    unit = normalize(v1)
    lines.append(describe("unit a =", unit))
    lines.append("a.b = {0:.3f}".format(dot_product(v1, v2)))
    lines.append("angle = {0:.3f} deg".format(angle_between(v1, v2)))
    return "\n".join(lines)

if __name__ == "__main__":
    v_a = (3.0, 4.0)
    v_b = (1.0, 2.0)
    sum_v = add_vectors(v_a, v_b)
    print(sum_v)
    dot_v = dot_product(v_a, v_b)
    print(dot_v)
    print(report(v_a, v_b))
    for factor in [0.5, 3.0]:
        scaled = scale_vector(v_a, factor)
        print(describe("scaled a =", scaled))

