NUMERIC = (int, float)
MEASURES = ("area", "perimeter")


def validate_dimension(name, value):
    if not isinstance(value, NUMERIC):
        raise TypeError("{0} must be numeric: {1}".format(name, type(value).__name__))
    if value <= 0:
        raise ValueError("{0} must be positive: {1}".format(name, value))
    return float(value)


def validate_dimensions(width, height):
    checked_width = validate_dimension("width", width)
    checked_height = validate_dimension("height", height)
    return checked_width, checked_height


def compute_area(width, height):
    checked = validate_dimensions(width, height)
    return checked[0] * checked[1]


def compute_perimeter(width, height):
    checked = validate_dimensions(width, height)
    return 2.0 * (checked[0] + checked[1])


def create_rectangle(width, height):
    validate_dimensions(width, height)
    return width, height


def scale_rectangle(rect_tuple, factor):
    if not isinstance(factor, NUMERIC):
        raise TypeError("factor must be numeric")
    if factor <= 0:
        raise ValueError("factor must be positive: {0}".format(factor))
    width, height = rect_tuple
    validate_dimensions(width, height)
    return width * factor, height * factor


def describe_rectangle(rect_tuple):
    width, height = rect_tuple
    return {
        "width": float(width),
        "height": float(height),
        "area": compute_area(width, height),
        "perimeter": compute_perimeter(width, height),
        "shape": "square" if width == height else "oblong",
    }


def format_report(rect_tuple, label="rectangle"):
    info = describe_rectangle(rect_tuple)
    dims = "{0:g} x {1:g}".format(info["width"], info["height"])
    lines = ["{0}: {1}".format(label, dims)]
    for key in MEASURES:
        lines.append("  {0} = {1:.2f}".format(key, info[key]))
    lines.append("  shape: {0}".format(info["shape"]))
    return "\n".join(lines)


if __name__ == "__main__":
    width = 10
    height = 20
    area = compute_area(width, height)
    perimeter = compute_perimeter(width, height)
    size = "{0:g} x {1:g}".format(width, height)
    print("{0} area = {1:.2f}".format(size, area))
    print("{0} perimeter = {1:.2f}".format(size, perimeter))

    r = create_rectangle(width, height)
    print(format_report(r, "original"))

    scaled_rect = scale_rectangle(r, 2)
    print(scaled_rect)
    print(format_report(scaled_rect, "scaled x2"))

