def normalize_spacing(text, max_iters):
    if max_iters < 0:
        raise ValueError("max_iters must be non-negative")
    for _ in range(max_iters):
        squeezed = text.replace("  ", " ")
        if squeezed == text:
            break
        text = squeezed
    return text


def create_pair(word1, word2):
    return (word1, word2)


def apply_substitutions(text, subs):
    for old, new in subs:
        text = text.replace(old, new)
    return text


def validate_subs(subs):
    for index, pair in enumerate(subs):
        if len(pair) != 2:
            raise ValueError("rule {} is not a pair".format(index))
        if not all(isinstance(item, str) for item in pair):
            raise TypeError("rule {} must contain only strings".format(index))
    return len(subs)


def normalize_text(
    text, subs,
    max_iters,
):
    validate_subs(subs)
    substituted = apply_substitutions(text.strip(), subs)
    return normalize_spacing(substituted, max_iters)


REPORT_KEYS = (
    "original_length",
    "normalized_length",
    "word_count",
    "rule_count",
)


def summarize(
    original, normalized,
    subs,
):
    summary = {}
    summary["original_length"] = len(original)
    summary["normalized_length"] = len(normalized)
    summary["word_count"] = len(normalized.split())
    summary["rule_count"] = len(subs)
    return summary


def format_report(summary):
    lines = []
    for key in REPORT_KEYS:
        label = key.replace("_", " ")
        lines.append("{:<20}{}".format(label, summary[key]))
    return "\n".join(lines)


def format_rules(subs):
    rendered = []
    for old, new in subs:
        rendered.append("{} -> {}".format(old, new))
    return ", ".join(rendered)


if __name__ == "__main__":
    subs = []
    subs.append(create_pair("foo", "bar"))
    subs.append(create_pair("baz", "qux"))
    sample = "   foo   baz   and    foo   again  "
    print("rules:", format_rules(subs))
    substituted = apply_substitutions(sample, subs)
    print("substituted:", repr(substituted))
    cleaned = normalize_text(
        sample, subs,
        12,
    )
    print("normalized:", repr(cleaned))
    stats = summarize(
        sample, cleaned,
        subs,
    )
    print(format_report(stats))
    limited = normalize_spacing(sample.strip(), 1)
    print("one pass:", repr(limited))

