import math

SEQUENCE_TYPES = (tuple, list)
NUMBER_TYPES = (int, float)


def impedance_magnitude(resistance, reactance):
    """Magnitude of the impedance: sqrt(R^2 + X^2)."""
    return math.hypot(resistance, reactance)


def impedance_phase(resistance, reactance):
    """Phase angle in radians: arctan(X / R)."""
    return math.atan2(reactance, resistance)


def _validate_component(component):
    """Return the (resistance, reactance) pair of a single circuit."""
    if not isinstance(component, SEQUENCE_TYPES):
        raise TypeError("each component must be a tuple of resistance and reactance")
    if len(component) != 2:
        raise ValueError("each component needs exactly two values")
    for value in component:
        if type(value) not in NUMBER_TYPES:
            raise TypeError("resistance and reactance must be real numbers")
    resistance, reactance = component
    if resistance == 0 and reactance == 0:
        raise ValueError("a circuit cannot have zero resistance and zero reactance")
    return float(resistance), float(reactance)


def impedance(components):
    """Total impedance (magnitude, phase) for a list of series circuits."""
    if not isinstance(components, SEQUENCE_TYPES):
        raise TypeError("components must be a list of tuples")
    results = []
    for component in components:
        resistance, reactance = _validate_component(component)
        magnitude = impedance_magnitude(resistance, reactance)
        phase = impedance_phase(resistance, reactance)
        rounded_magnitude = round(magnitude, 4)
        rounded_phase = round(phase, 4)
        results.append((rounded_magnitude, rounded_phase))
    return results


def describe_circuit(reactance):
    """Tell whether a circuit is inductive, capacitive or purely resistive."""
    if reactance > 0:
        return "inductive"
    if reactance < 0:
        return "capacitive"
    return "resistive"


def format_report(components, results):
    """Build one human readable line per analysed circuit."""
    lines = []
    for index, component in enumerate(components):
        resistance, reactance = component
        magnitude, phase = results[index]
        inputs = "R={0:.2f} ohm | X={1:.2f} ohm".format(resistance, reactance)
        outputs = "|Z|={0:.4f} ohm | phi={1:.4f} rad".format(magnitude, phase)
        kind = describe_circuit(reactance)
        lines.append(inputs + " -> " + outputs + " (" + kind + ")")
    return lines


def main():
    circuits = [
        (3, 4),
        (5, 12),
        (10, -10),
        (8, 0),
        (0.5, 1.5),
    ]
    results = impedance(circuits)
    print(results)
    for line in format_report(circuits, results):
        print(line)


if __name__ == "__main__":
    main()

