import math
import numbers


def area(major, minor):
    return math.pi * major * minor


def focal_distance(major, minor):
    return math.sqrt(major * major - minor * minor)


def eccentricity(major, minor):
    return focal_distance(major, minor) / major


def validate(major, minor):
    named_axes = [
        ("semi major axis", major),
        ("semi minor axis", minor),
    ]
    for name, value in named_axes:
        if not isinstance(value, numbers.Real):
            raise TypeError("{} must be numeric, got {!r}".format(name, value))
        if value <= 0:
            raise ValueError("{} must be positive, got {}".format(name, value))
    if minor > major:
        raise ValueError("semi minor {} exceeds semi major {}".format(minor, major))


def measure(ellipses):
    results = []
    for major, minor in ellipses:
        validate(major, minor)
        ell_area = area(major, minor)
        ecc = eccentricity(major, minor)
        measurement = (
            round(ell_area, 3),
            round(ecc, 3),
        )
        results.append(measurement)
    return results


def classify(ecc):
    if ecc < 0.1:
        return "circular"
    if ecc < 0.4:
        return "slightly elongated"
    if ecc < 0.75:
        return "elongated"
    return "highly elongated"


def format_report(ellipses, measurements):
    row_template = "{:>10g} {:>10g} {:>14.3f} {:>14.3f} {:>20}"
    header = "{:>10} {:>10} {:>14} {:>14} {:>20}".format(
        "major",
        "minor",
        "area",
        "eccentricity",
        "shape",
    )
    lines = [header, "-" * len(header)]
    rows = zip(ellipses, measurements)
    for axes, values in rows:
        major, minor = axes
        ell_area, ecc = values
        lines.append(row_template.format(
            major,
            minor,
            ell_area,
            ecc,
            classify(ecc),
        ))
    return "\n".join(lines)


def summarize(measurements):
    areas = [values[0] for values in measurements]
    eccs = [values[1] for values in measurements]
    return {
        "count": len(measurements),
        "total_area": round(sum(areas), 3),
        "mean_eccentricity": round(sum(eccs) / len(eccs), 3),
        "widest": max(areas),
    }


def main():
    ellipses = [
        (5, 3),
        (10, 10),
        (7.5, 2.5),
        (12, 6),
    ]
    measurements = measure(ellipses)
    print(format_report(ellipses, measurements))
    stats = summarize(measurements)
    print("\n{} ellipses, total area {}, mean eccentricity {}, widest {}".format(
        stats["count"],
        stats["total_area"],
        stats["mean_eccentricity"],
        stats["widest"],
    ))


if __name__ == "__main__":
    main()

