def square_size(width, height):
    """Return the side length of the largest square fitting in the image."""
    return min(width, height)


def axis_offset(dimension, size):
    """Return the offset that centres a crop of `size` inside `dimension`."""
    return (dimension - size) // 2


def crop_offset(width, height):
    """Return the (x, y) offsets that centre a square crop in one image."""
    size = square_size(width, height)
    horizontal = axis_offset(width, size)
    vertical = axis_offset(height, size)
    return (horizontal, vertical)


def check_dimension(label, value):
    """Raise if a single width or height is not a positive integer."""
    if not isinstance(value, int):
        raise TypeError("{} is not an integer".format(label))
    if value <= 0:
        raise ValueError("{} must be positive".format(label))


def validate(images):
    """Check that every entry is a pair of positive integers."""
    for index, image in enumerate(images):
        if not isinstance(image, tuple) or len(image) != 2:
            raise ValueError(f"image {index} is not a (width, height) pair")
        check_dimension(f"image {index} width", image[0])
        check_dimension(f"image {index} height", image[1])


def crop(images):
    """Return the crop offsets that centre a square in each image."""
    validate(images)
    offsets = []
    for image in images:
        offsets.append(crop_offset(*image))
    return offsets


def crop_boxes(images):
    """Return full crop rectangles as left/top/right/bottom tuples."""
    boxes = []
    for image in images:
        size = square_size(*image)
        corner = crop_offset(*image)
        far = (corner[0] + size, corner[1] + size)
        boxes.append(corner + far)
    return boxes


def describe(image, box):
    """Format one image and its crop rectangle as a readable line."""
    width, height = image
    left = box[0]
    top = box[1]
    size = box[2] - left
    position = f"({left}, {top})"
    return f"{width}x{height} -> square {size} at {position}"


def report(images):
    """Build one description line per image."""
    boxes = crop_boxes(images)
    lines = []
    for index, image in enumerate(images):
        lines.append(describe(image, boxes[index]))
    return lines


def main():
    images = [
        (100, 80),
        (80, 100),
        (64, 64),
        (1920, 1080),
        (3, 10),
    ]
    for line in report(images):
        print(line)
    print("offsets:", crop(images))


if __name__ == "__main__":
    main()

