def axis_delta(a, b):
    """Absolute difference between two integer coordinates."""
    return abs(a - b)


def manhattan(dx, dy):
    """Manhattan distance built from two axis deltas."""
    return dx + dy


def chebyshev(dx, dy):
    """Chebyshev distance built from two axis deltas."""
    return max(dx, dy)


def check_coordinate(value):
    """Raise unless the value is a plain integer coordinate."""
    if isinstance(value, bool):
        raise TypeError("coordinates must be integers, not booleans")
    if not isinstance(value, int):
        raise TypeError("coordinates must be integers")
    return value


def validate_point(point):
    """Return a point as an (x, y) pair of integers."""
    try:
        x, y = point
    except (TypeError, ValueError):
        raise ValueError("each point must be a pair of coordinates")
    check_coordinate(x)
    check_coordinate(y)
    return (x, y)


def validate_path(path):
    """Return a validated start/end pair of points."""
    try:
        start, end = path
    except (TypeError, ValueError):
        raise ValueError("each path must be a pair of points")
    return (validate_point(start), validate_point(end))


def navigate(paths):
    """Return a (manhattan, chebyshev) tuple for every start/end pair."""
    results = []
    for path in paths:
        start, end = validate_path(path)
        dx = axis_delta(start[0], end[0])
        dy = axis_delta(start[1], end[1])
        straight = manhattan(dx, dy)
        diagonal = chebyshev(dx, dy)
        results.append((straight, diagonal))
    return results


def point_text(point):
    """Render a point as "(x, y)"."""
    x, y = point
    return f"({x}, {y})"


def format_row(path, distances):
    """Render one journey and its two distances as a single text line."""
    start, end = path
    straight, diagonal = distances
    origin = point_text(start)
    target = point_text(end)
    return f"{origin} -> {target}: manhattan={straight} chebyshev={diagonal}"


def report(paths):
    """Build a printable report for a batch of journeys."""
    distances = navigate(paths)
    rows = zip(paths, distances)
    lines = []
    for path, pair in rows:
        lines.append(format_row(path, pair))
    total = sum(pair[0] for pair in distances)
    longest = max(pair[1] for pair in distances) if distances else 0
    lines.append(f"total manhattan={total} longest chebyshev step={longest}")
    return "\n".join(lines)


def main():
    journeys = [
        ((0, 0),
         (3, 4)),
        ((-2, 5),
         (6, -1)),
        ((7, 7),
         (7, 7)),
        ((1, -3),
         (-4, 2)),
    ]
    print(report(journeys))


if __name__ == "__main__":
    main()

