import math
import numbers


def _validate_sides(base, height):
    sides = (base, height)
    if any(not isinstance(side, numbers.Real) for side in sides):
        raise TypeError("base and height must be real numbers")
    if any(side <= 0 for side in sides):
        raise ValueError("base and height must be positive")


def hypotenuse(base, height):
    _validate_sides(base, height)
    return math.hypot(base, height)


def area(base, height):
    _validate_sides(base, height)
    return base * height / 2


def perimeter(base, height):
    return base + height + hypotenuse(base, height)


def triangles(shapes):
    results = []
    for base, height in shapes:
        triangle_area = area(base, height)
        triangle_perimeter = perimeter(base, height)
        results.append((triangle_area, triangle_perimeter))
    return results


def summarize(results):
    total_area = sum(result[0] for result in results)
    total_perimeter = sum(result[1] for result in results)
    return (total_area, total_perimeter)


def format_row(index, base, height, values):
    triangle_area, triangle_perimeter = values
    template = "{:>3} {:>8.2f} {:>8.2f} {:>10.2f} {:>10.2f}"
    return template.format(index, base, height, triangle_area, triangle_perimeter)


def report(shapes):
    computed = triangles(shapes)
    header = "{:>3} {:>8} {:>8} {:>10} {:>10}".format("#", "base", "height", "area", "perim")
    rows = [header, "-" * len(header)]
    for index in range(len(shapes)):
        base, height = shapes[index]
        rows.append(format_row(index + 1, base, height, computed[index]))
    totals = summarize(computed)
    rows.append("-" * len(header))
    rows.append("{:>3} {:>8} {:>8} {:>10.2f} {:>10.2f}".format("", "", "", totals[0], totals[1]))
    return "\n".join(rows)


def main():
    shapes = [
        (3, 4),
        (5, 12),
        (8, 15),
        (7, 24),
        (2.5, 6),
    ]
    print(report(shapes))
    print("computed:", triangles(shapes))


if __name__ == "__main__":
    main()

