def pad_right(text, width):
    """Return text padded with spaces on the right to reach width."""
    if width < 0:
        raise ValueError("width must not be negative")
    return text + " " * max(0, width - len(text))


def pad_left(text, width):
    """Return text padded with spaces on the left to reach width."""
    if width < 0:
        raise ValueError("width must not be negative")
    return " " * max(0, width - len(text)) + text


def normalize_row(row):
    """Coerce a two element row into a pair of strings."""
    left, right = row
    return str(left), str(right)


def column_widths(rows):
    """Return the maximum length of the left and of the right column."""
    left_width = 0
    right_width = 0
    for row in rows:
        left, right = normalize_row(row)
        left_width = max(left_width, len(left))
        right_width = max(right_width, len(right))
    return left_width, right_width


def align(rows):
    """Format a two column table, returning padded (left, right) tuples."""
    left_width, right_width = column_widths(rows)
    aligned = []
    for row in rows:
        left, right = normalize_row(row)
        padded_left = pad_right(left, left_width)
        padded_right = pad_left(right, right_width)
        aligned.append((padded_left, padded_right))
    return aligned


def render(rows, separator="  "):
    """Join every aligned row into a single printable block of text."""
