from math import log2

BASELINE_BITS = 128.0
STRENGTH_BANDS = [
    (0.25, "weak"),
    (0.50, "fair"),
    (0.75, "strong"),
]
MIN_POOL_SIZE = 2


def _validate(password, pool_size):
    if not isinstance(password, str):
        raise TypeError("password must be a string, got {}".format(type(password).__name__))
    if not password:
        raise ValueError("password must not be empty")
    if not isinstance(pool_size, int):
        raise TypeError("pool size must be an integer, got {}".format(type(pool_size).__name__))
    if pool_size < MIN_POOL_SIZE:
        raise ValueError("pool size must be at least {} (got {})".format(MIN_POOL_SIZE, pool_size))


def entropy_bits(password, pool_size):
    _validate(password, pool_size)
    return len(password) * log2(pool_size)


def strength_score(password, pool_size):
    raw = entropy_bits(password, pool_size) / BASELINE_BITS
    return min(raw, 1.0)


def classify(score):
    for limit, label in STRENGTH_BANDS:
        if score < limit:
            return label
    return "excellent"


def entropy(passwords):
    results = []
    for password, pool_size in passwords:
        bits = entropy_bits(password, pool_size)
        score = strength_score(password, pool_size)
        rounded_bits = round(bits, 2)
        rounded_score = round(score, 2)
        results.append((rounded_bits, rounded_score))
    return results


def format_report(passwords, results):
    template = "{:<26} pool={:<4} entropy={:>7} bits  score={:.2f}  {}"
    lines = []
    for index in range(len(results)):
        password = passwords[index][0]
        pool_size = passwords[index][1]
        bits, score = results[index]
        label = classify(score)
        lines.append(template.format(
            password,
            pool_size,
            bits,
            score,
            label,
        ))
    return "\n".join(lines)


def weakest(passwords, results):
    ranked = sorted(range(len(results)), key=lambda i: results[i][0])
    index = ranked[0]
    return passwords[index][0], results[index][0]


def main():
    samples = [
        ("hunter12", 64),
        ("abc", 26),
        ("Tr0ub4dor&3", 94),
        ("correcthorsebatterystaple", 26),
        ("qX7!mZ2@pL9#vB4$wR8%", 94),
    ]
    results = entropy(samples)
    print(format_report(samples, results))
    lowest = weakest(samples, results)
    print("weakest: {} with {} bits".format(lowest[0], lowest[1]))


if __name__ == "__main__":
    main()

