def parse_version(text):
    """Split a version string such as '1.2' into an integer (major, minor) pair."""
    parts = text.strip().split(".")
    if len(parts) != 2:
        raise ValueError("version must have exactly two components: " + text)
    major, minor = parts
    if not (major.isdigit() and minor.isdigit()):
        raise ValueError("version components must be numeric: " + text)
    return int(major), int(minor)


def compare_versions(old, new):
    """Return (major_increased, minor_increased) for the two version strings."""
    old_major, old_minor = parse_version(old)
    new_major, new_minor = parse_version(new)
    return new_major > old_major, new_minor > old_minor


def compare(versions):
    """Map every (old, new) string pair onto its boolean increase pair."""
    results = []
    for pair in versions:
        old, new = pair
        results.append(compare_versions(old, new))
    return results


def describe(pair, flags):
    """Build a one-line human readable summary of a single comparison."""
    old, new = pair
    major_up, minor_up = flags
    if major_up and minor_up:
        kind = "major and minor bump"
    elif major_up:
        kind = "major bump"
    elif minor_up:
        kind = "minor bump"
    else:
        kind = "no increase"
    return f"{old} -> {new}: {kind} (major={major_up}, minor={minor_up})"


def format_report(versions, results):
    """Join the summaries of all comparisons into a printable report."""
    lines = []
    paired = zip(versions, results)
    for item in paired:
        lines.append(describe(item[0], item[1]))
    return "\n".join(lines)


def count_changes(results):
    """Count how many comparisons increased the major and the minor number."""
    major_count = sum(1 for flags in results if flags[0])
    minor_count = sum(1 for flags in results if flags[1])
    return major_count, minor_count


def main():
    updates = [
        ("1.0", "1.2"),
        ("1.9", "2.0"),
        ("2.3", "3.7"),
        ("4.5", "4.5"),
        ("0.8", "1.1"),
    ]
    results = compare(updates)
    print(format_report(updates, results))
    major_count, minor_count = count_changes(results)
    print(f"{major_count} major increases out of {len(results)} updates")
    print(f"{minor_count} minor increases out of {len(results)} updates")


if __name__ == "__main__":
    main()

