LIMITS = (0, 7)


def forward_diagonals(row, col):
    """Destinations one step ahead of (row, col), to the left and to the right."""
    left = row - 1, col - 1
    right = row - 1, col + 1
    return [left, right]


def backward_diagonals(row, col):
    """Destinations one step behind (row, col), to the left and to the right."""
    left = row + 1, col - 1
    right = row + 1, col + 1
    return [left, right]


def within_limits(row, col):
    """Report whether the row and the column each fall inside the board limits."""
    low, high = LIMITS
    return low <= row <= high, low <= col <= high


def diagonals(pieces):
    """All legal diagonal destinations for every piece on the board."""
    destinations = []
    for row, col in pieces:
        candidates = forward_diagonals(row, col)
        candidates.extend(backward_diagonals(row, col))
        for dest in candidates:
            if all(within_limits(*dest)):
                destinations.append(dest)
    return destinations


def parse_piece(token):
    """Turn a 'row,col' string into an integer pair, rejecting anything else."""
    parts = token.replace(" ", "").split(",")
    if len(parts) != 2:
        raise ValueError("a piece needs exactly a row and a column: " + token)
    row, col = (int(part) for part in parts)
    if not all(within_limits(row, col)):
        raise ValueError("piece off the board: " + token)
    return row, col


def parse_board(tokens):
    return [parse_piece(token) for token in tokens]


def format_cell(cell):
    return "({0}, {1})".format(*cell)


def format_moves(piece, moves):
    listing = ", ".join(format_cell(move) for move in moves)
    return format_cell(piece) + " -> " + (listing or "no moves")


def report(pieces):
    lines = []
    for piece in pieces:
        moves = diagonals([piece])
        lines.append(format_moves(piece, moves))
    lines.append("total destinations: {0}".format(len(diagonals(pieces))))
    return "\n".join(lines)


def main():
    tokens = [
        "0,0", "3,4",
        "7,7", "5, 0",
    ]
    board = parse_board(tokens)
    print(report(board))


if __name__ == "__main__":
    main()

