"""Character frequency statistics for simple language models."""


def bump(counts, char):
    """Return the old count for *char* and the updated count as a pair."""
    old = counts.get(char, 0)
    new = old + 1
    counts[char] = new
    return old, new


def swap(char, count):
    """Return the pair (count, char) built from a character and its count."""
    return count, char


def count_characters(text):
    """Count every character of *text*, returning a dict of char -> count."""
    counts = {}
    for char in text:
        bump(counts, char)
    return counts


def ranked_pairs(counts):
    """Sort the (count, char) pairs from most to least frequent."""
    pairs = []
    for char, count in counts.items():
        pairs.append(swap(char, count))
    pairs.sort(key=lambda pair: (-pair[0], pair[1]))
    return pairs


def frequencies(text):
    """Return the highest character count and its character as a pair."""
    if not isinstance(text, str):
        raise TypeError("frequencies() expects a string, got %r" % type(text).__name__)
    if not text:
        return 0, ""
    return ranked_pairs(count_characters(text))[0]


def describe(char):
    """Give a printable name for a character, naming the invisible ones."""
    names = {
        " ": "space",
        "\t": "tab",
        "\n": "newline",
        "\r": "return",
    }
    return names.get(char, repr(char))


def report(text, top=3):
    """Format a short frequency report listing the *top* most common chars."""
    pairs = ranked_pairs(count_characters(text))
    lines = ["sample: %s" % repr(text[:32])]
    total = sum(count for count, _char in pairs)
    lines.append("characters: %d total | %d distinct" % (total, len(pairs)))
    for count, char in pairs[:top]:
        share = 100.0 * count / total
        lines.append(f"  {describe(char):<9} {count:>3}  {share:>5.1f}%")
    return "\n".join(lines)


def main():
    samples = [
        "hello world",
        "mississippi river",
        "the quick brown fox jumps over the lazy dog",
    ]
    for sample in samples:
        print(report(sample))
        count, char = frequencies(sample)
        print("winner: %s seen %d times\n" % (describe(char), count))


if __name__ == "__main__":
    main()

