def order_times(first, second):
    """Return the two times as (larger, smaller)."""
    if first >= second:
        return first, second
    return second, first


def parse_sample(entry):
    """Coerce a raw (amplitude, time) entry into floats."""
    amplitude, time = entry
    return float(amplitude), float(time)


def peaks(samples):
    """Return the (time, amplitude) pairs whose amplitude is a peak."""
    result = []
    for entry in samples:
        amplitude, time = parse_sample(entry)
        verdict = classify(amplitude, time)
        if verdict[0]:
            result.append((verdict[1], amplitude))
    return result


def peak_span(found):
    """Return (latest, earliest) peak time, or (0.0, 0.0) when no peaks exist."""
    if not found:
        return 0.0, 0.0
    latest = found[0][0]
    earliest = latest
    for time, _amplitude in found[1:]:
        latest = order_times(latest, time)[0]
        earliest = order_times(earliest, time)[1]
    return latest, earliest


def format_report(found):
    """Build the printable lines describing the detected peaks."""
    lines = ["peaks detected: {}".format(len(found))]
    for time, amplitude in found:
        lines.append("  t={:6.2f}s  a={:7.2f}".format(time, amplitude))
    latest, earliest = peak_span(found)
    lines.append("span: {:.2f}s .. {:.2f}s".format(earliest, latest))
    return lines


