    waveform = [
        (3.5, 0.0),
        (12.25, 0.1),
        (9.99, 0.2),
        (10.0, 0.3),
        (41.0, 0.4),
        (-18.5, 0.5),
        (23.75, 0.6),
        (0.5, 0.7),
    ]
    found = peaks(waveform)
    for line in format_report(found):
        print(line)


if __name__ == "__main__":
    main()

