DISTANCE = 12.0
NUMBER_TYPES = (int, float)


def downstream_speed(paddle, current):
    return paddle + current


def upstream_speed(paddle, current):
    return abs(paddle - current)


def round_trip_time(paddle, current):
    down = downstream_speed(paddle, current)
    up = upstream_speed(paddle, current)
    if down == 0 or up == 0:
        return float('inf')
    return DISTANCE / down + DISTANCE / up


def efficiency_ratio(paddle, current):
    return paddle ** 2 - current ** 2


def validate_speed(name, value):
    if not isinstance(value, NUMBER_TYPES):
        raise TypeError('%s speed must be numeric: %r' % (name, value))
    if value < 0:
        raise ValueError('%s speed must not be negative: %r' % (name, value))
    return float(value)


def navigate(speeds):
    results = []
    for pair in speeds:
        paddle = validate_speed('paddle', pair[0])
        current = validate_speed('current', pair[1])
        down = downstream_speed(paddle, current)
        up = upstream_speed(paddle, current)
        results.append((down, up))
        trip = round_trip_time(paddle, current)
        efficiency = efficiency_ratio(paddle, current)
        results.append((trip, efficiency))
    return results


def format_number(value):
    if value == float('inf'):
        return 'inf'
    if float(value).is_integer():
        return str(int(value))
    return '%.2f' % value


def format_report(speeds, metrics):
    header = (
        'paddle',
        'current',
        'down',
        'up',
        'trip',
        'eff',
    )
    lines = [' | '.join('%8s' % column for column in header)]
    for index, pair in enumerate(speeds):
        row = list(pair) + list(metrics[2 * index]) + list(metrics[2 * index + 1])
        lines.append(' | '.join('%8s' % format_number(cell) for cell in row))
    return '\n'.join(lines)


def main():
    trips = [
        (5, 3),
        (4, 4),
        (10, 2),
        (7.5, 1.5),
        (6, 0),
    ]
    metrics = navigate(trips)
    print(format_report(trips, metrics))
    fastest = min(range(len(trips)), key=lambda i: metrics[2 * i + 1][0])
    paddle, current = trips[fastest]
    print('Fastest round trip: paddle %s current %s time %s hours' % (
        format_number(paddle),
        format_number(current),
        format_number(metrics[2 * fastest + 1][0]),
    ))


if __name__ == '__main__':
    main()

