import math
import numbers

HEADINGS = (
    "drop",
    "run",
    "distance",
    "gradient",
    "speed",
    "safety",
)
WIDTHS = (
    6,
    6,
    9,
    10,
    8,
    8,
)


def slope_distance(drop, run):
    exact = math.hypot(drop, run)
    return round(exact, 1)


def gradient_percent(drop, run):
    return round(drop / run * 100.0, 1)


def glide_speed(drop, run):
    return round(math.sqrt(19.6 * drop), 1)


def safety_rating(drop, run):
    return round(run ** 2 / drop, 1)


def validate(pair):
    if len(pair) != 2:
        raise ValueError("each slope needs a drop and a run: %r" % (pair,))
    named = zip(HEADINGS, pair)
    for name, value in named:
        if not isinstance(value, numbers.Real):
            raise TypeError("{} must be numeric but was {!r}".format(name, value))
        if value <= 0:
            raise ValueError("{} must be positive: {}".format(name, value))
    drop, run = pair
    return float(drop), float(run)


def evaluate(slopes):
    results = []
    for pair in slopes:
        drop, run = validate(pair)
        distance = slope_distance(drop, run)
        gradient = gradient_percent(drop, run)
        speed = glide_speed(drop, run)
        safety = safety_rating(drop, run)
        results.append((distance, gradient))
        results.append((speed, safety))
    return results


def format_row(values):
    cells = []
    sized = zip(WIDTHS, values)
    for width, value in sized:
        cells.append("{:>{}}".format(value, width))
    return " ".join(cells)


def format_report(slopes, metrics):
    lines = [format_row(HEADINGS)]
    lines.append("-" * len(lines[0]))
    for index, pair in enumerate(slopes):
        drop, run = pair
        distance, gradient = metrics[2 * index]
        speed, safety = metrics[2 * index + 1]
        row = (
            drop,
            run,
            distance,
            "{}%".format(gradient),
            speed,
            safety,
        )
        lines.append(format_row(row))
    return "\n".join(lines)


def steepest(slopes):
    def gradient_of(pair):
        return gradient_percent(pair[0], pair[1])

    return max(slopes, key=gradient_of)


def main():
    slopes = [
        (30, 40),
        (120, 300),
        (75, 75),
        (45, 180),
    ]
    metrics = evaluate(slopes)
    print(format_report(slopes, metrics))
    drop, run = steepest(slopes)
    gradient = gradient_percent(drop, run)
    print(f"steepest: {drop}m drop over {run}m run at {gradient}%")


if __name__ == "__main__":
    main()

