import math

EFFICIENCY = 0.2
THERMAL_FRACTION = 0.8
BASE_RESISTANCE = 10


def ideal_power(area, irradiance):
    return area * irradiance


def usable_power(area, irradiance):
    return ideal_power(area, irradiance) * EFFICIENCY


def thermal_loss(area, irradiance):
    return ideal_power(area, irradiance) * THERMAL_FRACTION


def estimated_voltage(area, irradiance):
    power = usable_power(area, irradiance) * BASE_RESISTANCE
    return math.sqrt(power)


def rounded_pair(first, second):
    left = round(first, 1)
    right = round(second, 1)
    return left, right


def validate_panel(index, panel):
    if len(panel) != 2:
        raise ValueError("panel {} must hold exactly two values".format(index))
    numeric = (int, float)
    for value in panel:
        if not isinstance(value, numeric):
            raise TypeError("panel {} has a non-numeric reading".format(index))
        if value < 0:
            raise ValueError("panel {} has a negative reading".format(index))
    return float(panel[0]), float(panel[1])


def solar(panels):
    results = []
    for index in range(len(panels)):
        panel = validate_panel(index, panels[index])
        area = panel[0]
        irradiance = panel[1]
        ideal = ideal_power(area, irradiance)
        usable = usable_power(area, irradiance)
        thermal = thermal_loss(area, irradiance)
        volts = estimated_voltage(area, irradiance)
        results.append(rounded_pair(ideal, usable))
        results.append(rounded_pair(thermal, volts))
    return results


def format_report(panels, metrics):
    lines = ["area  irrad  ideal  usable  thermal  volts"]
    for index in range(len(panels)):
        cells = list(panels[index])
        cells.extend(metrics[2 * index])
        cells.extend(metrics[2 * index + 1])
        lines.append("  ".join("{:>5g}".format(cell) for cell in cells))
    return "\n".join(lines)


def farm_totals(metrics):
    ideal = sum(pair[0] for pair in metrics[0::2])
    usable = sum(pair[1] for pair in metrics[0::2])
    thermal = sum(pair[0] for pair in metrics[1::2])
    labelled = []
    labelled.append(("ideal", ideal))
    labelled.append(("usable", usable))
    labelled.append(("thermal", thermal))
    return labelled


def main():
    readings = []
    readings.append((2, 500))
    readings.append((1.5, 800))
    readings.append((3, 250))
    metrics = solar(readings)
    print(format_report(readings, metrics))
    for name, total in farm_totals(metrics):
        print("farm {}: {:g} W".format(name, total))


if __name__ == "__main__":
    main()

