SPEED_OF_SOUND = 340.0
GAP_METERS = 10000.0
PRECISION = 2
NUMERIC_TYPES = (int, float)


def frequency_multiplier(source, observer):
    """Doppler factor for a source closing in on the observer."""
    return (SPEED_OF_SOUND + observer) / (SPEED_OF_SOUND - source)


def closing_speed(source, observer):
    """Rate at which the gap between source and observer shrinks."""
    return source + observer


def compression_factor(source, observer):
    """Fraction of the original wavelength that survives the motion."""
    return 1 - source / SPEED_OF_SOUND


def echo_time(source, observer):
    """Seconds for a pulse to cross the gap and come back."""
    return 2 * GAP_METERS / closing_speed(source, observer)


def truncate(value):
    """Cut a metric down to two decimals without rounding upward."""
    scale = 10 ** PRECISION
    return int(value * scale) / scale


def validate_pair(pair, position):
    """Coerce one input pair to floats, rejecting unusable combinations."""
    values = list(pair)
    if len(values) != 2:
        raise ValueError("pair %d must hold exactly two speeds" % position)
    source = values[0]
    observer = values[1]
    if not isinstance(source, NUMERIC_TYPES):
        raise TypeError("source speed in pair %d is not numeric" % position)
    if not isinstance(observer, NUMERIC_TYPES):
        raise TypeError("observer speed in pair %d is not numeric" % position)
    if source >= SPEED_OF_SOUND:
        raise ValueError("source speed in pair %d is supersonic" % position)
    if closing_speed(source, observer) == 0:
        raise ValueError("pair %d has no closing speed" % position)
    return float(source), float(observer)


def acoustic(velocities):
    """Return two metric pairs for every (source, observer) speed pair."""
    results = []
    for position, pair in enumerate(velocities):
        checked = validate_pair(pair, position)
        source = checked[0]
        observer = checked[1]
        multiplier = truncate(frequency_multiplier(source, observer))
        closing = truncate(closing_speed(source, observer))
        compression = truncate(compression_factor(source, observer))
        echo = truncate(echo_time(source, observer))
        results.append((multiplier, closing))
        results.append((compression, echo))
    return results


def format_report(velocities, metrics):
    """Turn raw inputs and computed metrics into printable lines."""
    lines = []
    for position, pair in enumerate(velocities):
        first = metrics[2 * position]
        second = metrics[2 * position + 1]
        head = f"src={pair[0]:.1f} obs={pair[1]:.1f}"
        shift = f"x{first[0]:.2f} closing={first[1]:.2f} m/s"
        wave = f"lambda={second[0]:.2f} echo={second[1]:.2f} s"
        lines.append(f"{head} -> {shift} | {wave}")
    return lines


def main():
    samples = [
        (40, 10),
        (20, 5),
        (85, -15),
        (0, 30),
    ]
    for line in format_report(samples, acoustic(samples)):
        print(line)


if __name__ == "__main__":
    main()

