        raise ValueError("length must be positive, got %r" % (length,))
    return float(length),float(delta_t)


def thermal(materials):
    results = []
    for scenario in materials:
        length,delta_t = validate(scenario)
        results.append((
            expansion(length,delta_t),
            final_length(length,delta_t),
        ))
        results.append((
            strain_percent(length,delta_t),
            confined_stress(length,delta_t),
        ))
    return results


def format_row(scenario,pairs):
    length,delta_t = scenario
    growth_pair,load_pair = pairs
    grown,ending = growth_pair
    strain,stress = load_pair
    fields = [
        "L0=%.3f m" % length,
        "dT=%+.1f C" % delta_t,
        "dL=%.5f m" % grown,
        "L1=%.5f m" % ending,
        "strain=%.4f %%" % strain,
        "stress=%.1f MPa" % stress,
    ]
    return " | ".join(fields)


def report(materials):
    metrics = thermal(materials)
    lines = []
    for index,scenario in enumerate(materials):
        start = 2 * index
        lines.append(format_row(scenario,metrics[start:start + 2]))
    return "\n".join(lines)


def main():
    scenarios = [
        (10,50),
        (2.5,-20),
        (100,12.5),
        (0.75,300),
    ]
    print(report(scenarios))
    total = sum(pair[0] for pair in thermal(scenarios)[0::2])
    print("total expansion %.5f m over %d scenarios" % (total,len(scenarios)))


if __name__ == "__main__":
    main()

