SONIC_BOOM_FACTOR = 2.5
NUMERIC_TYPES = (int, float)
PAIR_TYPES = (list, tuple)
METRIC_NAMES = (
    "mach",
    "dynamic_pressure",
    "heat_friction",
    "boom_radius",
)


def mach_number(speed, speed_of_sound):
    return speed / speed_of_sound


def dynamic_pressure_proxy(speed, speed_of_sound):
    return speed * speed / speed_of_sound


def heat_friction_proxy(speed, speed_of_sound):
    return max(speed - speed_of_sound, 0)


def sonic_boom_radius(speed, speed_of_sound):
    return speed * SONIC_BOOM_FACTOR


def _validate(index, reading):
    if not isinstance(reading, PAIR_TYPES):
        raise TypeError("reading %d must be a pair of numbers" % index)
    if len(reading) != 2:
        raise ValueError("reading %d must hold exactly two values" % index)
    for value in reading:
        if not isinstance(value, NUMERIC_TYPES):
            raise TypeError("reading %d contains a non-numeric value" % index)
    if reading[1] <= 0:
        raise ValueError("reading %d has a non-positive speed of sound" % index)


def aerodynamics(flights):
    results = []
    for index, reading in enumerate(flights):
        _validate(index, reading)
        speed, speed_of_sound = reading
        mach = mach_number(speed, speed_of_sound)
        dynamic = dynamic_pressure_proxy(speed, speed_of_sound)
        heat = heat_friction_proxy(speed, speed_of_sound)
        boom = sonic_boom_radius(speed, speed_of_sound)
        results.append((mach, dynamic))
        results.append((heat, boom))
    return results


def format_report(flights, results):
    lines = []
    for index, reading in enumerate(flights):
        speed, speed_of_sound = reading
        metrics = list(results[2 * index]) + list(results[2 * index + 1])
        parts = []
        for name, value in zip(METRIC_NAMES, metrics):
            parts.append(f"{name}={value:.2f}")
        header = f"flight {index + 1}: speed={speed} sound={speed_of_sound}"
        lines.append(header + " -> " + ", ".join(parts))
    return "\n".join(lines)


def main():
    flights = [
        (600, 300),
        (250, 340),
        (1020, 340),
        (340, 340),
    ]
    results = aerodynamics(flights)
    print(format_report(flights, results))
    print("total pairs produced:", len(results))


if __name__ == "__main__":
    main()

