        counts[1] += speed_breaches[1] + heat_breaches[1]
    return counts


def format_report(label,counts):
    warnings,shutdowns = counts
    parts = [
        "{} warning(s)".format(warnings),
        "{} shutdown(s)".format(shutdowns),
    ]
    joined = ", ".join(parts)
    return "{}: {}".format(label,joined)


def main():
