VALLEY_DRAFT = 3.0
STORM_GUST = 8.0
WIND_SLOW_LIMIT = 40.0
WIND_CLOSE_LIMIT = 60.0
ICE_SLOW_LIMIT = 5.0
ICE_CLOSE_LIMIT = 10.0
HOLIDAY_CLOSE_BONUS = 1.10


def exceeds_with_draft(value, limit):
    """True when the value plus the valley draft strictly exceeds the limit."""
    return value + VALLEY_DRAFT > limit


def exceeds_with_gust(value, limit):
    """True when the value plus the storm gust strictly exceeds the limit."""
    return value + STORM_GUST > limit


def parse_reading(line):
    """Split one report line into a wind gust and an ice thickness."""
    parts = line.split()
    if len(parts) != 2:
        raise ValueError("expected 'gust thickness' but received: " + line)
    return float(parts[0]), float(parts[1])


def parse_conditions(conditions):
    """Turn the multiline report into a list of readings, skipping blank lines."""
    readings = []
    for line in conditions.splitlines():
        stripped = line.strip()
        if stripped:
            readings.append(parse_reading(stripped))
    return readings


def skilift(conditions, holiday):
    counts = [0, 0]
    wind_close_limit = WIND_CLOSE_LIMIT
    if holiday:
        wind_close_limit = WIND_CLOSE_LIMIT * HOLIDAY_CLOSE_BONUS
    for wind, ice in parse_conditions(conditions):
        if exceeds_with_draft(wind, WIND_SLOW_LIMIT):
