text_nat:
HUMIDITY_BLUR = 1.1
ROLLER_SLIP = 1.2
HIGHRES_JAM_FACTOR = 0.8

SMEAR_LIMITS = (2.0, 5.0)
ALIGN_LIMITS = (1.5, 3.0)


def exceeds_reprint(value, reprint_limit):
    """True when the humidity-blurred value strictly exceeds the reprint limit."""
    return value * HUMIDITY_BLUR > reprint_limit


def exceeds_jam(value, jam_limit):
    """True when the roller-slipped value strictly exceeds the jam limit."""
    return value * ROLLER_SLIP > jam_limit


def parse_line(line):
    """Split one log line into its ink smear and alignment error."""
    fields = line.split()
    if len(fields) != 2:
        raise ValueError("expected 'smear alignment', got {!r}".format(line))
    return float(fields[0]), float(fields[1])


def smear_limits(highres):
    """Return the smear reprint and jam limits, tightened for high resolution."""
    reprint_limit, jam_limit = SMEAR_LIMITS
    if highres:
        jam_limit *= HIGHRES_JAM_FACTOR
    return reprint_limit, jam_limit


def printer(pages, highres):
    """Count reprint and jam events over every page described in the log."""
    counts = [0, 0]
    smear_reprint, smear_jam = smear_limits(highres)
    align_reprint, align_jam = ALIGN_LIMITS
    for line in pages.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        smear, alignment = parse_line(stripped)
        if exceeds_reprint(smear, smear_reprint):
            counts[0] += 1
        if exceeds_reprint(alignment, align_reprint):
            counts[0] += 1
        if exceeds_jam(smear, smear_jam):
            counts[1] += 1
        if exceeds_jam(alignment, align_jam):
            counts[1] += 1
    return counts


def format_report(counts, highres):
    """Render the event counts as a single readable line."""
    mode = "high-res" if highres else "draft"
    parts = ["mode={}".format(mode)]
    parts.append("reprints={}".format(counts[0]))
    parts.append("jams={}".format(counts[1]))
    return ", ".join(parts)


def main():
    """Evaluate a sample batch in both printing modes."""
    log = """1.9 1.4
4.5 2.8
0.3 0.2
5.0 3.1"""
    for highres in (False, True):
        counts = printer(log, highres)
        print(format_report(counts, highres))
    single = printer("1.9 1.4", False)
    print(format_report(single, False))


if __name__ == "__main__":
    main()

