WATERLOGGED = 500.0
ICE = 1000.0
CONTAINER_HEAVY = 20000.0
CONTAINER_UNSAFE = 30000.0
DECK_HEAVY = 50000.0
DECK_UNSAFE = 80000.0
ROUGH_FACTOR = 0.9


def is_heavy(value, limit):
    return value + WATERLOGGED > limit


def is_unsafe(value, limit):
    return value + ICE > limit


def parse_line(line):
    parts = line.split()
    if len(parts) != 2:
        raise ValueError("expected two values per line, got: %r" % line)
    return float(parts[0]), float(parts[1])


def parse_manifests(manifests):
    rows = []
    for index, line in enumerate(manifests.splitlines()):
        stripped = line.strip()
        if not stripped:
            continue
        try:
            container, deck = parse_line(stripped)
        except ValueError as exc:
            raise ValueError("line %d: %s" % (index + 1, exc))
        rows.append((container, deck))
    return rows


