def exceeds_warning(value, warning_limit):
    return value * RUST_FACTOR > warning_limit


def exceeds_danger(value, danger_limit):
    return value * STAGNATION_FACTOR > danger_limit


def parse_line(line):
    parts = line.split()
    if len(parts) != 2:
        raise ValueError("expected two values per line: " + line)
