AXLE_LIMITS = (3.0, 6.0)
WEIGHT_LIMITS = (8000.0, 20000.0)
WEEKEND_OVERSIZE_FACTOR = 0.9


def exceeds_commercial(value, limit):
    """True when the value plus a ten percent trailer sway passes the limit."""
    return value * 1.1 > limit


def exceeds_oversize(value, limit):
    """True when the value plus a twenty percent wet road slip passes the limit."""
    return value * 1.2 > limit


def parse_line(line, line_number):
    """Return the axle count and weight recorded on one reading line."""
    fields = line.split()
    if len(fields) != 2:
        raise ValueError("line {}: expected an axle count and a weight".format(line_number))
    raw_axles, raw_weight = fields
    try:
        axles = float(raw_axles)
        weight = float(raw_weight)
    except ValueError:
        raise ValueError("line {}: non numeric reading".format(line_number))
    if axles <= 0 or weight <= 0:
        raise ValueError("line {}: readings must be positive".format(line_number))
    return axles, weight


def toll(vehicles, weekend):
    counts = [0, 0]
    axle_commercial, axle_oversize = AXLE_LIMITS
    weight_commercial, weight_oversize = WEIGHT_LIMITS
    if weekend:
        weight_oversize *= WEEKEND_OVERSIZE_FACTOR
    for offset, line in enumerate(vehicles.splitlines()):
        if not line.strip():
            continue
        reading = parse_line(line, offset + 1)
        axles, weight = reading
        if exceeds_commercial(axles, axle_commercial):
            counts[0] += 1
        if exceeds_commercial(weight, weight_commercial):
            counts[0] += 1
        if exceeds_oversize(axles, axle_oversize):
            counts[1] += 1
        if exceeds_oversize(weight, weight_oversize):
            counts[1] += 1
    return counts


def format_report(label, counts):
    commercial, oversize = counts
    head = "{:<10} commercial={}".format(label, commercial)
    return "{} oversize={}".format(head, oversize)


def main():
    weekday_readings = "2.8 7500.0\n4.0 9000.0"
    weekend_readings = "5.5 18500.0\n6.0 21000.0"
    counts = toll(weekday_readings, False)
    print(format_report("weekday", counts))
    counts = toll(weekend_readings, True)
    print(format_report("weekend", counts))


if __name__ == "__main__":
    main()

