text_nat:
NUMERIC_TYPES = (int, float)

SEVERE_LABEL = "severe scorching"

RISK_BANDS = (
    (5.0, "even"),
    (15.0, "mild scorching"),
    (40.0, "uneven"),
)


def validate_temperature(name, value):
    if not isinstance(value, NUMERIC_TYPES):
        raise TypeError("%s temperature must be numeric" % name)
    if value <= 0:
        raise ValueError("%s temperature must be above absolute zero" % name)
    return float(value)


def thermal_average(bean, air):
    return (bean + air) / 2


def temperature_gradient(bean, air):
    return abs(air - bean)


def heat_transfer_rate(bean, air):
    average = thermal_average(bean, air)
    return (bean * air) / average


def scorch_risk_index(bean, air):
    gradient = temperature_gradient(bean, air)
    average = thermal_average(bean, air)
    return (gradient ** 2) / average


def analyze(bean, air):
    transfer = heat_transfer_rate(bean, air)
    scorch = scorch_risk_index(bean, air)
    return transfer + scorch


METRIC_HELPERS = (
    ("thermal average", thermal_average),
    ("temperature gradient", temperature_gradient),
    ("heat transfer rate", heat_transfer_rate),
    ("scorch risk index", scorch_risk_index),
)

REPORT_LABELS = (
    "thermal average",
    "temperature gradient",
    "heat transfer rate",
    "scorch risk index",
    "roast score",
)


def collect_metrics(bean, air):
    clean_bean = validate_temperature("bean", bean)
    clean_air = validate_temperature("air", air)
    metrics = {}
    for label, helper in METRIC_HELPERS:
        metrics[label] = helper(clean_bean, clean_air)
    metrics["roast score"] = analyze(clean_bean, clean_air)
    return metrics


def classify_roast(bean, air):
    risk = scorch_risk_index(bean, air)
    for limit, label in RISK_BANDS:
        if risk < limit:
            return label
    return SEVERE_LABEL


def format_report(bean, air):
    metrics = collect_metrics(bean, air)
    lines = ["Roast profile: bean=%s / air=%s" % (bean, air)]
    for label in REPORT_LABELS:
        lines.append("  %-20s %s" % (label, metrics[label]))
    lines.append("  verdict: %s" % classify_roast(bean, air))
    return "\n".join(lines)


if __name__ == "__main__":
    bean = 200
    air = 250
    print(analyze(bean, air))
    print(format_report(bean, air))

