    if not isinstance(value, numeric):
        raise TypeError("{0} hours must be numeric".format(name))
    if value <= 0:
        raise ValueError("{0} hours must be positive".format(name))


def validate_schedule(fasting, eating):
    _check_hours("fasting", fasting)
    _check_hours("eating", eating)
    total = fasting + eating
    if total > 24:
        raise ValueError("cycle of {0}h exceeds a day".format(total))
    return total


def cycle_duration(fasting, eating):
    return fasting + eating


def imbalance_metric(fasting, eating):
    return abs(fasting - 2 * eating)


def metabolic_score(fasting, eating):
    duration = cycle_duration(fasting, eating)
    return fasting * eating / duration


def autophagy_index(fasting, eating):
    imbalance = imbalance_metric(fasting, eating)
    duration = cycle_duration(fasting, eating)
    return imbalance ** 2 / duration


def score(fasting, eating):
    metabolic = metabolic_score(fasting, eating)
    autophagy = autophagy_index(fasting, eating)
    return metabolic + autophagy


def classify(total):
    if total < 4.0:
        return "gentle"
    if total < 6.0:
