NUMERIC_TYPES = (int, float)

METRIC_ORDER = [
    "total",
    "overlap",
    "efficiency",
    "risk",
    "score",
]


def validate_duration(name, value):
    if not isinstance(value, NUMERIC_TYPES):
        raise TypeError("invalid {} duration type: {!r}".format(name, value))
    if value < 0:
        raise ValueError("negative {} duration: {}".format(name, value))


def validate_durations(intake, exhaust):
    validate_duration("intake", intake)
    validate_duration("exhaust", exhaust)
    if total_open_duration(intake, exhaust) == 0:
        raise ValueError("total open duration must be positive")


def total_open_duration(intake, exhaust):
    return intake + exhaust


def overlap_duration(intake, exhaust):
    return abs(intake - exhaust)


def flow_efficiency(intake, exhaust):
    total = total_open_duration(intake, exhaust)
    return (intake * exhaust) / total


def backpressure_risk(intake, exhaust):
    overlap = overlap_duration(intake, exhaust)
    total = total_open_duration(intake, exhaust)
    return (overlap * overlap) / total


def diagnose(intake, exhaust):
    validate_durations(intake, exhaust)
    efficiency = flow_efficiency(intake, exhaust)
    risk = backpressure_risk(intake, exhaust)
    return efficiency + risk


def collect_metrics(intake, exhaust):
    validate_durations(intake, exhaust)
    metrics = {}
    metrics["total"] = total_open_duration(intake, exhaust)
    metrics["overlap"] = overlap_duration(intake, exhaust)
    metrics["efficiency"] = flow_efficiency(intake, exhaust)
    metrics["risk"] = backpressure_risk(intake, exhaust)
    metrics["score"] = diagnose(intake, exhaust)
    return metrics


def format_report(intake, exhaust):
    metrics = collect_metrics(intake, exhaust)
    lines = ["valve timing report: intake={} exhaust={}".format(intake, exhaust)]
    for key in METRIC_ORDER:
        lines.append("  {:<10} {}".format(key, metrics[key]))
    return "\n".join(lines)


def classify(intake, exhaust):
    score = diagnose(intake, exhaust)
    bands = [
        (90, "poor"),
        (120, "marginal"),
        (160, "acceptable"),
    ]
    for limit, label in bands:
        if score < limit:
            return label
    return "optimal"


if __name__ == "__main__":
    intake = 240
    exhaust = 220
    print(diagnose(intake, exhaust))
    print(format_report(intake, exhaust))
