def _validate(descent, ascent):
    rates = [
        ("descent", descent),
        ("ascent", ascent),
    ]
    for name, rate in rates:
        if not isinstance(rate, NUMERIC_TYPES):
            raise TypeError("%s rate must be numeric, got %r" % (name, rate))
        if rate <= 0:
            raise ValueError("%s rate must be positive, got %r" % (name, rate))


NUMERIC_TYPES = (int, float)


def combined_speed(descent, ascent):
    _validate(descent, ascent)
    return descent + ascent


def velocity_differential(descent, ascent):
    _validate(descent, ascent)
    return abs(descent - ascent)


def ballast_efficiency(descent, ascent):
    total = combined_speed(descent, ascent)
    return (descent * ascent) / total


def hull_stress_index(descent, ascent):
    differential = velocity_differential(descent, ascent)
    total = combined_speed(descent, ascent)
    return (differential * differential) / total


def calculate(descent, ascent):
    efficiency = ballast_efficiency(descent, ascent)
    stress = hull_stress_index(descent, ascent)
    return efficiency + stress


def dive_metrics(descent, ascent):
    return {
        "descent": descent,
        "ascent": ascent,
        "combined_speed": combined_speed(descent, ascent),
        "velocity_differential": velocity_differential(descent, ascent),
        "ballast_efficiency": ballast_efficiency(descent, ascent),
        "hull_stress_index": hull_stress_index(descent, ascent),
        "dive_metric": calculate(descent, ascent),
    }


