def validate_counts(rows, stitches):
    counts = (rows, stitches)
    for value in counts:
        if not isinstance(value, NUMERIC_TYPES):
            raise TypeError("row and stitch counts must be numbers")
        if value <= 0:
            raise ValueError("row and stitch counts must be positive")
    return counts


NUMERIC_TYPES = (int, float)

TENSION_BANDS = [
    (8.0, "loose"),
    (12.0, "balanced"),
    (16.0, "firm"),
]


def total_loops(rows, stitches):
    return rows + stitches


def gauge_skew(rows, stitches):
    return abs(rows - stitches)


def drape_factor(rows, stitches):
    loops = total_loops(rows, stitches)
    return (rows * stitches) / loops


def firmness_index(rows, stitches):
    skew = gauge_skew(rows, stitches)
    loops = total_loops(rows, stitches)
    return (skew ** 2) / loops


def gauge(rows, stitches):
    drape = drape_factor(rows, stitches)
    firmness = firmness_index(rows, stitches)
    return drape + firmness


def classify_tension(score):
    for limit, label in TENSION_BANDS:
        if score < limit:
            return label
    return "over-tight"


def measure_swatch(rows, stitches):
    validate_counts(rows, stitches)
    return {
        "rows": rows,
        "stitches": stitches,
        "loops": total_loops(rows, stitches),
        "skew": gauge_skew(rows, stitches),
        "drape": drape_factor(rows, stitches),
        "firmness": firmness_index(rows, stitches),
        "gauge": gauge(rows, stitches),
    }


