    data = measure_swatch(rows, stitches)
    label = classify_tension(data["gauge"])
    parts = [
        "swatch {0}x{1}".format(data["rows"], data["stitches"]),
        "loops={0} skew={1}".format(data["loops"], data["skew"]),
        "drape={0} firmness={1}".format(data["drape"], data["firmness"]),
        "gauge={0} ({1})".format(data["gauge"], label),
    ]
    return " | ".join(parts)


