def total_mass(flour, water):
    return flour + water


def ingredient_difference(flour, water):
    return abs(flour - water)


def gluten_network_score(flour, water):
    mass = total_mass(flour, water)
    return (flour * water) / mass


def stickiness_index(flour, water):
    difference = ingredient_difference(flour, water)
    mass = total_mass(flour, water)
    return (difference * difference) / mass


def hydration_percent(flour, water):
    return (water / flour) * 100.0


def validate_weights(flour, water):
    numeric_types = (int, float)
    labels = ("flour", "water")
    weights = (flour, water)
    for pair in zip(labels, weights):
        name, value = pair
        if not isinstance(value, numeric_types):
            raise TypeError("{} weight must be numeric but got {}".format(name, type(value)))
        if value <= 0:
            raise ValueError("{} weight must be positive but got {}".format(name, value))


def knead(flour, water):
    validate_weights(flour, water)
    network = gluten_network_score(flour, water)
    stickiness = stickiness_index(flour, water)
    return network + stickiness


def classify_dough(flour, water):
    hydration = hydration_percent(flour, water)
    thresholds = (
        60.0,
        75.0,
        90.0,
    )
    names = (
        "stiff",
        "standard",
        "slack",
        "batter",
    )
    position = 0
    for limit in thresholds:
        if hydration >= limit:
            position = position + 1
    return names[position]


def formula_summary(flour, water):
    labels = (
        "Total dough mass",
        "Ingredient difference",
        "Gluten network score",
        "Stickiness index",
        "Hydration percent",
        "Dough type",
    )
    values = (
        total_mass(flour, water),
        ingredient_difference(flour, water),
        gluten_network_score(flour, water),
        stickiness_index(flour, water),
        hydration_percent(flour, water),
        classify_dough(flour, water),
    )
    lines = []
    for pair in zip(labels, values):
        label, value = pair
        lines.append("{:<22} {}".format(label, value))
    return "\n".join(lines)


if __name__ == "__main__":
    flour_weight = 500
    water_weight = 350
    print(formula_summary(flour_weight, water_weight))
    print(knead(flour_weight, water_weight))

