EIGHT_HOUR_SHIFT = 8.0
BONUS_DIVISOR = 10.0
NUMERIC = (int, float)


def _validate(items, hours):
    """Reject records that cannot produce a meaningful rate."""
    if not isinstance(items, NUMERIC):
        raise TypeError("items must be a number, got {!r}".format(items))
    if not isinstance(hours, NUMERIC):
        raise TypeError("hours must be a number, got {!r}".format(hours))
    if hours <= 0:
        raise ValueError("hours must be positive: {!r}".format(hours))
    if items < 0:
        raise ValueError("items must not be negative: {!r}".format(items))


def production_rate(items, hours):
    """Items produced per hour worked."""
    _validate(items, hours)
    return items / float(hours)


def expected_output(rate, hours):
    """Output an eight hour shift would yield at the same rate."""
    _validate(rate, hours)
    return rate * EIGHT_HOUR_SHIFT


def bonus_multiplier(rate, items):
    """Rate scaled down by ten, never larger than the items produced."""
    return min(rate / BONUS_DIVISOR, float(items))


def evaluate(shifts):
    """Return a list of (expected_output, bonus_multiplier) per shift record."""
    results = []
    for record in shifts:
        items, hours = record
        rate = production_rate(items, hours)
        expected = expected_output(rate, hours)
        bonus = bonus_multiplier(rate, items)
        results.append((expected, bonus))
    return results


def format_row(label, cells):
    """Render one report line: a label followed by right aligned cells."""
    body = "".join("{:>12}".format(cell) for cell in cells)
    return "{:<8}".format(label) + body


def build_report(shifts):
    """Tabulate the evaluated metrics for a batch of shift records."""
    metrics = evaluate(shifts)
    headings = ["Expected", "Bonus"]
    lines = [format_row("Shift", headings)]
    for index, pair in enumerate(metrics):
        expected, bonus = pair
        cells = ["{:.2f}".format(expected), "{:.2f}".format(bonus)]
        lines.append(format_row(index + 1, cells))
    return "\n".join(lines)


def main():
    shifts = [
        (150, 5),
        (80, 4),
        (12, 8),
        (300, 10),
    ]
    print(build_report(shifts))


if __name__ == "__main__":
    main()

