import math

TARGET_DAY = 30
PRECISION = 2
NUMERIC = (int, float)
HEADER = "  height   days    index     day-30"


def growth_rate(height, days):
    """Average daily growth in centimeters per day."""
    if days <= 0:
        raise ValueError("days since planting must be positive")
    return height / days


def maturity_index(rate, days):
    """Growth rate scaled by the square root of the elapsed days."""
    return rate * math.sqrt(days)


def expected_height(rate, height):
    """Projected height once the plant reaches the thirty day mark."""
    elapsed = height / rate if rate else 0.0
    return height + rate * (TARGET_DAY - elapsed)


def parse_record(record):
    """Split a raw pair into a validated (height, days) couple."""
    try:
        height, days = record
    except (TypeError, ValueError):
        raise ValueError("each sample must be a height/days pair")
    if not isinstance(height, NUMERIC):
        raise TypeError("height must be numeric")
    if not isinstance(days, NUMERIC):
        raise TypeError("days must be numeric")
    if height <= 0:
        raise ValueError("height must be positive")
    return float(height), int(days)


def monitor(plants):
    """Compute (maturity index, expected height) for every sample."""
    results = []
    for record in plants:
        height, days = parse_record(record)
        rate = growth_rate(height, days)
        index = maturity_index(rate, days)
        projection = expected_height(rate, height)
        results.append((round(index, PRECISION),
                        round(projection, PRECISION)))
    return results


def format_row(record, metrics):
    """Render one monitored sample as an aligned text line."""
    height, days = parse_record(record)
    index, projection = metrics
    cells = ["{:>8.1f}".format(height),
             "{:>6d}".format(days),
             "{:>8.2f}".format(index),
             "{:>10.2f}".format(projection)]
    return " ".join(cells)


def format_report(plants, results):
    """Build the full text report for the monitored samples."""
    lines = [HEADER, "-" * len(HEADER)]
    for pair in zip(plants, results):
        lines.append(format_row(*pair))
    return "\n".join(lines)


def main():
    samples = [
        (10.0, 5),
        (22.5, 12),
        (4.0, 2),
        (48.0, 25),
        (31.5, 18),
    ]
    results = monitor(samples)
    print(format_report(samples, results))
    best = max(results, key=lambda metrics: metrics[0])
    print("\ntop index {:.2f} projects to {:.2f} cm".format(best[0], best[1]))
    average = sum(metrics[1] for metrics in results) / len(results)
    print("mean height at day {}: {:.2f} cm".format(TARGET_DAY, average))


if __name__ == "__main__":
    main()

