def _validate(visitors, purchases):
    if visitors <= 0:
        raise ValueError("visitors must be positive, got {}".format(visitors))
    if purchases < 0 or purchases > visitors:
        raise ValueError("purchases {} out of range for visitors {}".format(purchases, visitors))


def conversion_rate(purchases, visitors):
    _validate(visitors, purchases)
    return purchases / visitors


def lost_revenue(rate, visitors):
    return visitors * (1 - rate) * 2


def target_visitors(rate, purchases):
    if rate <= 0:
        return float("inf")
    current = purchases / rate
    return current * (1000 / purchases)


def forecast(campaigns):
    results = []
    for campaign in campaigns:
        visitors, purchases = campaign
        rate = conversion_rate(purchases, visitors)
        revenue_lost = lost_revenue(rate, visitors)
        needed = target_visitors(rate, purchases)
        results.append((revenue_lost, needed))
    return results


def format_row(campaign, result):
    visitors, purchases = campaign
    revenue_lost, needed = result
    rate = conversion_rate(purchases, visitors)
    cells = [
        "{:>8}".format(visitors),
        "{:>10}".format(purchases),
        "{:>7.2%}".format(rate),
        "{:>12,.2f}".format(revenue_lost),
        "{:>12,.0f}".format(needed),
    ]
    return " | ".join(cells)


def format_header():
    columns = [
        "Visitors",
        " Purchases",
        "   Rate",
        "   Lost ($)",
        "  Target",
    ]
    return " | ".join(columns)


def format_report(campaigns, results):
    header = format_header()
    rule = "-" * len(header)
    lines = [header, rule]
    for index, campaign in enumerate(campaigns):
        lines.append(format_row(campaign, results[index]))
    total_lost = sum(result[0] for result in results)
    lines.append(rule)
    lines.append("Total theoretical lost revenue: ${:,.2f}".format(total_lost))
    return "\n".join(lines)


def main():
    campaigns = [
        (1000, 50),
        (2500, 125),
        (8000, 640),
        (400, 4),
    ]
    results = forecast(campaigns)
    print(format_report(campaigns, results))


if __name__ == "__main__":
    main()

