import math

NUMERIC = (int,float)


def validate_point(point):
    if len(point) != 2:
        raise ValueError("each shift point needs exactly two values")
    front,rear = point
    for value in (front,rear):
        if not isinstance(value,NUMERIC):
            raise TypeError("teeth counts must be numeric")
    return float(front),float(rear)


def tension_pair(front,rear):
    derailleur_diagonal = math.hypot(front,rear)
    shifting_bias = math.copysign(front,rear)
    high_gear_tension = max(derailleur_diagonal,shifting_bias)
    low_climbing_slack = min(derailleur_diagonal,shifting_bias)
    rounded_high = round(high_gear_tension,1)
    rounded_low = round(low_climbing_slack,1)
    rounded = (rounded_high,rounded_low)
    raw = (derailleur_diagonal,shifting_bias)
    return [rounded,raw]


def evaluate(shifts):
    results = []
    for point in shifts:
        front,rear = validate_point(point)
        results.extend(tension_pair(front,rear))
    return results


def gear_ratio(dataset):
    front,rear = validate_point(dataset[0])
    if rear == 0:
        return float("inf")
    return front / rear


def format_profile(dataset,results):
    front,rear = validate_point(dataset[0])
    rounded = results[0]
    raw = results[1]
    lines = [
        f"front={front:g}, rear={rear:g}",
        f"  rounded high/low: {rounded[0]}, {rounded[1]}",
        f"  raw diagonal/bias: {raw[0]:.6f}, {raw[1]:.6f}",
        f"  ratio: {gear_ratio(dataset):.3f}, entries: {len(results)}",
    ]
    return "\n".join(lines)


def main():
    road_setup = [[50.0,20.0]]
    gravel_setup = [[46.0,36.0]]
    reverse_setup = [[34.0,-28.0]]
    datasets = [
        road_setup,
        gravel_setup,
        reverse_setup,
    ]
    for dataset in datasets:
        results = evaluate(dataset)
        print(format_profile(dataset,results))
        print(results)


if __name__ == "__main__":
    main()

