def parse_dive(dive):
    difficulty_text, execution_text = dive.split('-')
    return int(difficulty_text), int(execution_text)


def total_score(difficulty, execution):
    return difficulty * execution


def average_judge_score(difficulty, execution):
    return execution / 3


def is_elite(difficulty, execution):
    return difficulty > 3


def is_flawless(difficulty, execution):
    return execution == 30


def validate_dive(dive):
    parts = dive.split('-')
    if len(parts) != 2:
        raise ValueError('expected format difficulty-execution, got {!r}'.format(dive))
    for part in parts:
        if not part.strip().isdigit():
            raise ValueError('non-numeric field {!r} in {!r}'.format(part, dive))
    return dive


def describe_dive(difficulty, execution):
    labels = []
    if is_elite(difficulty, execution):
        labels.append('elite')
    if is_flawless(difficulty, execution):
        labels.append('flawless')
    if not labels:
        labels.append('standard')
    header = '{}-{}'.format(difficulty, execution)
    tags = ', '.join(labels)
    return '{} [{}]'.format(header, tags)


def score(dives):
    elite_totals = []
    flawless_averages = []
    for dive in dives:
        difficulty, execution = parse_dive(validate_dive(dive))
        if is_elite(difficulty, execution):
            elite_totals.append(total_score(difficulty, execution))
        if is_flawless(difficulty, execution):
            flawless_averages.append(average_judge_score(difficulty, execution))
    return elite_totals, flawless_averages


def report(dives):
    lines = [describe_dive(*parse_dive(validate_dive(dive))) for dive in dives]
    elite_totals, flawless_averages = score(dives)
    lines.append('elite totals: {}'.format(elite_totals))
    lines.append('flawless averages: {}'.format(flawless_averages))
    return '\n'.join(lines)


