def parse_shot(spec):
    """Split 'distance-aperture' and return the two integers as a tuple."""
    parts = spec.strip().split("-")
    if len(parts) != 2:
        raise ValueError("expected 'distance-aperture', got {!r}".format(spec))
    distance_text, aperture_text = parts
    if not distance_text.isdigit() or not aperture_text.isdigit():
        raise ValueError(
            "non numeric distance/aperture in {!r}".format(spec)
        )
    return int(distance_text), int(aperture_text)


def guide_number(distance, aperture):
    """Guide number of the flash: distance times aperture."""
    return distance * aperture


def optimal_sensitivity(distance, aperture):
    """Optimal ISO: the guide number scaled by one hundred."""
    return guide_number(distance, aperture) * 100


def is_close_up(distance, aperture):
    """A shot is a close up when the subject is nearer than two metres."""
    return distance < 2


def is_wide_open(distance, aperture):
    """A shot is wide open when the aperture number is below three."""
    return aperture < 3


def describe_shot(distance, aperture):
    """One readable line of exposure data for a single shot."""
    tags = []
    if is_close_up(distance, aperture):
        tags.append("close-up")
    if is_wide_open(distance, aperture):
        tags.append("wide-open")
    label = ", ".join(tags) or "standard"
    return "d={}m f/{} -> GN {}, ISO {} [{}]".format(
        distance,
        aperture,
        guide_number(distance, aperture),
        optimal_sensitivity(distance, aperture),
        label,
    )


def calculate(shots):
    """Collect close-up sensitivities and wide-open guide numbers."""
    sensitivities = []
    guide_numbers = []
    for spec in shots:
        distance, aperture = parse_shot(spec)
        if is_close_up(distance, aperture):
            sensitivities.append(optimal_sensitivity(distance, aperture))
        if is_wide_open(distance, aperture):
            guide_numbers.append(guide_number(distance, aperture))
    return sensitivities, guide_numbers


def format_summary(sensitivities, guide_numbers):
    """Render the two result lists as a short two line report."""
    iso_part = ", ".join(str(value) for value in sensitivities) or "none"
    gn_part = ", ".join(str(value) for value in guide_numbers) or "none"
    return "close-up ISO: {}\nwide-open GN: {}".format(
        iso_part,
        gn_part,
    )


def main():
    shots = [
        "1-2",
        "3-4",
        "2-1",
        "1-5",
        "4-8",
    ]
    for spec in shots:
        distance, aperture = parse_shot(spec)
        print(describe_shot(distance, aperture))
    sensitivities, guide_numbers = calculate(shots)
    print(format_summary(sensitivities, guide_numbers))


if __name__ == "__main__":
    main()

