def parse_combination(text):
    parts = text.split("-")
    if len(parts) != 2:
        raise ValueError("expected 'dial_one-dial_two', got {!r}".format(text))
    dial_one = int(parts[0].strip())
    dial_two = int(parts[1].strip())
    return dial_one, dial_two


def dial_distance(dial_one, dial_two):
    return abs(dial_one - dial_two)


def entropy_score(dial_one, dial_two):
    return dial_distance(dial_one, dial_two) * 10


def is_adjacent(dial_one, dial_two):
    return dial_distance(dial_one, dial_two) == 1


def is_opposite(dial_one, dial_two):
    return dial_distance(dial_one, dial_two) == 50


def assess(locks):
    adjacent_entropies = []
    opposite_distances = []
    for text in locks:
        dial_one, dial_two = parse_combination(text)
        if is_adjacent(dial_one, dial_two):
            adjacent_entropies.append(entropy_score(dial_one, dial_two))
        if is_opposite(dial_one, dial_two):
            opposite_distances.append(dial_distance(dial_one, dial_two))
    return adjacent_entropies, opposite_distances


def describe(text):
    dial_one, dial_two = parse_combination(text)
    labels = []
    if is_adjacent(dial_one, dial_two):
        labels.append("adjacent")
    if is_opposite(dial_one, dial_two):
        labels.append("opposite")
    if not labels:
        labels.append("ordinary")
    template = "{0}: dials {1} and {2}, distance {3}, entropy {4} ({5})"
    return template.format(
        text,
        dial_one,
        dial_two,
        dial_distance(dial_one, dial_two),
        entropy_score(dial_one, dial_two),
        ", ".join(labels),
    )


def summarise(adjacent_entropies, opposite_distances):
    lines = [
        "adjacent pairs: {0} (total entropy {1})".format(
            len(adjacent_entropies), sum(adjacent_entropies)
        ),
        "opposite pairs: {0} (total distance {1})".format(
            len(opposite_distances), sum(opposite_distances)
        ),
    ]
    return "\n".join(lines)


def main():
    locks = [
        "10-11",
        "0-50",
        "7-7",
        "99-98",
        "20-70",
        "33-41",
    ]
    for text in locks:
        print(describe(text))
    adjacent_entropies, opposite_distances = assess(locks)
    print(summarise(adjacent_entropies, opposite_distances))


if __name__ == "__main__":
    main()

