        "0-50",
        "7-7",
        "99-98",
        "20-70",
        "33-41",
    ]
    for text in locks:
        print(describe(text))
    adjacent_entropies,opposite_distances = assess(locks)
    print(summarise(adjacent_entropies,opposite_distances))


