def parse_fold(instruction):
    """Split 'horizontal-vertical' on the hyphen and return the two integers."""
    if not isinstance(instruction, str):
        raise TypeError("fold instruction must be a string")
    parts = instruction.strip().split("-")
    if len(parts) != 2:
        raise ValueError("expected an instruction of the form 'horizontal-vertical'")
    horizontal = int(parts[0])
    vertical = int(parts[1])
    return horizontal, vertical


def fold_squared_length(horizontal, vertical):
    """Return the squared length of the fold vector."""
    return horizontal * horizontal + vertical * vertical


def fold_area(horizontal, vertical):
    """Return the triangular area covered by the fold."""
    return horizontal * vertical / 2


def is_diagonal_fold(horizontal, vertical):
    """A fold is diagonal when both coordinates are exactly equal."""
    return horizontal == vertical


def is_large_fold(horizontal, vertical):
    """A fold is large when its area reaches fifty."""
    return fold_area(horizontal, vertical) >= 50


def crease(instructions):
    """Map fold instructions to diagonal squared lengths and large fold areas."""
    diagonals = []
    large = []
    for instruction in instructions:
        horizontal, vertical = parse_fold(instruction)
        if is_diagonal_fold(horizontal, vertical):
            diagonals.append(fold_squared_length(horizontal, vertical))
        if is_large_fold(horizontal, vertical):
            large.append(fold_area(horizontal, vertical))
    return diagonals, large


def describe_fold(instruction):
    """Build a one line human readable report for a single instruction."""
    horizontal, vertical = parse_fold(instruction)
    tags = []
    if is_diagonal_fold(horizontal, vertical):
        tags.append("diagonal")
    if is_large_fold(horizontal, vertical):
        tags.append("large")
    kind = ", ".join(tags) if tags else "plain"
    return "{}: length^2={}, area={}, kind={}".format(
        instruction,
        fold_squared_length(horizontal, vertical),
        fold_area(horizontal, vertical),
        kind,
    )


def main():
    instructions = [
        "10-10",
        "3-4",
        "12-20",
        "7-7",
        "2-100",
    ]
    for instruction in instructions:
        print(describe_fold(instruction))
    diagonals, large = crease(instructions)
    print("diagonal squared lengths:", diagonals)
    print("large fold areas:", large)


if __name__ == "__main__":
    main()

