HEAVY_THRESHOLD = 200


def parse_set(spec):
    """Split a 'bar-plates' string and return the two weights as integers."""
    parts = spec.split('-')
    if len(parts) != 2:
        raise ValueError("malformed set %r, expected 'bar-plates'" % spec)
    bar_text = parts[0].strip()
    plates_text = parts[1].strip()
    if not bar_text.isdigit() or not plates_text.isdigit():
        raise ValueError("non-numeric weights in %r" % spec)
    return int(bar_text), int(plates_text)


def total_weight(bar, plates):
    """Total weight on the bar."""
    return bar + plates


def unilateral_load(bar, plates):
    """Weight carried by one side of the bar."""
    return plates / 2


def is_heavy(bar, plates):
    """True when the total lift weight exceeds the heavy threshold."""
    return total_weight(bar, plates) > HEAVY_THRESHOLD


def is_balanced(bar, plates):
    """True when the plates can be split evenly between both sides."""
    return plates % 2 == 0


def lift(sets):
    heavy_loads = []
    balanced_totals = []
    for spec in sets:
        bar, plates = parse_set(spec)
        if is_heavy(bar, plates):
            heavy_loads.append(unilateral_load(bar, plates))
        if is_balanced(bar, plates):
            balanced_totals.append(total_weight(bar, plates))
    return heavy_loads, balanced_totals


def describe_set(spec):
    """Render one set as a readable line of totals and flags."""
    bar, plates = parse_set(spec)
    flags = []
    if is_heavy(bar, plates):
        flags.append('heavy')
    if is_balanced(bar, plates):
        flags.append('balanced')
    label = ', '.join(flags) or 'light'
    return '%s -> total %d, per side %.1f [%s]' % (
        spec,
        total_weight(bar, plates),
        unilateral_load(bar, plates),
        label,
    )


def format_summary(heavy_loads, balanced_totals):
    heavy_text = ', '.join('%.1f' % load for load in heavy_loads)
    balanced_text = ', '.join(str(total) for total in balanced_totals)
    lines = [
        'heavy sides: %s' % heavy_text,
        'balanced totals: %s' % balanced_text,
        'counts: %d heavy, %d balanced' % (len(heavy_loads), len(balanced_totals)),
    ]
    return '\n'.join(lines)


def main():
    workout = [
        '45-160',
        '35-45',
        '45-200',
        '20-90',
        '45-155',
    ]
    heavy_loads, balanced_totals = lift(workout)
    print(format_summary(heavy_loads, balanced_totals))
    for spec in workout:
        print(describe_set(spec))


if __name__ == '__main__':
    main()

