"""Utilities for observing and summarising solar eclipse durations."""


def parse_event(record):
    """Split 'totality-partial' and return the two minute counts as integers."""
    text = record.strip()
    if text.count("-") != 1:
        raise ValueError("event must look like 'totality-partial', got %r" % record)
    totality_text, partial_text = text.split("-")
    return int(totality_text), int(partial_text)


def total_duration(totality_minutes, partial_minutes):
    """Whole visible event length in minutes."""
    return totality_minutes + partial_minutes


def darkness_ratio(totality_minutes, partial_minutes):
    """Fraction of the event spent in full totality."""
    return totality_minutes / total_duration(totality_minutes, partial_minutes)


def is_deep_eclipse(totality_minutes, partial_minutes):
    """True when more than a tenth of the event is total darkness."""
    return darkness_ratio(totality_minutes, partial_minutes) > 0.1


def is_fleeting_event(totality_minutes, partial_minutes):
    """True when totality lasts under two minutes."""
    return totality_minutes < 2


def observe(events):
    """Collect deep-eclipse durations and fleeting-event darkness ratios."""
    deep_durations = []
    fleeting_ratios = []
    for record in events:
        totality_minutes, partial_minutes = parse_event(record)
        if is_deep_eclipse(totality_minutes, partial_minutes):
            deep_durations.append(total_duration(totality_minutes, partial_minutes))
        if is_fleeting_event(totality_minutes, partial_minutes):
            fleeting_ratios.append(darkness_ratio(totality_minutes, partial_minutes))
    return deep_durations, fleeting_ratios


def describe_event(record):
    """One-line human readable description of a single event string."""
    totality_minutes, partial_minutes = parse_event(record)
    labels = []
    if is_deep_eclipse(totality_minutes, partial_minutes):
        labels.append("deep")
    if is_fleeting_event(totality_minutes, partial_minutes):
        labels.append("fleeting")
    return "{0}: {1} min total, ratio {2:.3f} [{3}]".format(
        record,
        total_duration(totality_minutes, partial_minutes),
        darkness_ratio(totality_minutes, partial_minutes),
        ", ".join(labels) or "ordinary",
    )


def summarise(deep_durations, fleeting_ratios):
    """Build a short report from the two lists produced by observe()."""
    lines = ["deep eclipses: %d" % len(deep_durations)]
    if deep_durations:
        lines.append("longest deep event: %d min" % max(deep_durations))
    lines.append("fleeting events: %d" % len(fleeting_ratios))
    if fleeting_ratios:
        average = sum(fleeting_ratios) / len(fleeting_ratios)
        lines.append("mean fleeting ratio: %.3f" % average)
    return "\n".join(lines)


def main():
    events = "1-9 3-5 7-11 2-2 1-4".split()
    for record in events:
        print(describe_event(record))
    deep_durations, fleeting_ratios = observe(events)
    print(summarise(deep_durations, fleeting_ratios))


if __name__ == "__main__":
    main()

