def parse_pipe(spec):
    """Split 'radius-velocity' and return the two integers as a tuple."""
    text = spec.strip()
    if text.count("-") != 1:
        raise ValueError("expected 'radius-velocity', got {!r}".format(text))
    radius_text, velocity_text = text.split("-")
    if not radius_text.isdigit() or not velocity_text.isdigit():
        raise ValueError("non-numeric radius or velocity in {!r}".format(text))
    return int(radius_text), int(velocity_text)


def cross_section_area(radius, velocity):
    """Pipe radius squared, multiplied by three."""
    return radius * radius * 3


def overall_flow_rate(radius, velocity):
    """Cross section area multiplied by the water velocity."""
    return cross_section_area(radius, velocity) * velocity


def is_main_line(radius, velocity):
    """A main line has a radius greater than five."""
    return radius > 5


def is_high_pressure(radius, velocity):
    """High pressure means a velocity greater than ten."""
    return velocity > 10


def plumb(pipes):
    """Return (main line flow rates, high pressure cross section areas)."""
    main_flows = []
    pressure_areas = []
    for spec in pipes:
        radius, velocity = parse_pipe(spec)
        if is_main_line(radius, velocity):
            main_flows.append(overall_flow_rate(radius, velocity))
        if is_high_pressure(radius, velocity):
            pressure_areas.append(cross_section_area(radius, velocity))
    return main_flows, pressure_areas


def describe_pipe(spec):
    """Render one pipe specification as a single readable line."""
    radius, velocity = parse_pipe(spec)
    tags = []
    if is_main_line(radius, velocity):
        tags.append("main line")
    if is_high_pressure(radius, velocity):
        tags.append("high pressure")
    fields = [
        "r={}".format(radius),
        "v={}".format(velocity),
        "area={}".format(cross_section_area(radius, velocity)),
        "flow={}".format(overall_flow_rate(radius, velocity)),
    ]
    return " ".join(fields) + " ({})".format(", ".join(tags) or "branch")


def summarize(main_flows, pressure_areas):
    """Totals for the two collected lists."""
    parts = [
        "{} main lines totalling {} flow".format(len(main_flows), sum(main_flows)),
        "{} high pressure pipes totalling {} area".format(
            len(pressure_areas),
            sum(pressure_areas),
        ),
    ]
    return "; ".join(parts)


def main():
    pipes = [
        '6-12',
        '3-20',
        '9-4',
        '2-2',
        '7-11',
    ]
    for spec in pipes:
        print(describe_pipe(spec))
    main_flows, pressure_areas = plumb(pipes)
    print(summarize(main_flows, pressure_areas))
    print(plumb(['6-12']))


if __name__ == "__main__":
    main()

