SECONDS_PER_MINUTE = 60
SEQUENCE_TYPES = (list, tuple)
NUMBER_TYPES = (int, float)


def check_number(value, name):
    if not isinstance(value, NUMBER_TYPES):
        raise TypeError("%s must be numeric" % name)


def validate(data):
    if not isinstance(data, SEQUENCE_TYPES):
        raise TypeError("playback expects a list of two values")
    if len(data) != 2:
        raise ValueError("playback expects a duration and a multiplier")
    duration, multiplier = data
    check_number(duration, "duration")
    check_number(multiplier, "multiplier")
    if duration < 0:
        raise ValueError("duration cannot be negative")
    if multiplier <= 0:
        raise ValueError("multiplier must be positive")
    return duration, multiplier


def adjusted_duration(duration, multiplier):
    return duration / multiplier


def total_seconds(minutes, per_minute):
    return int(minutes * per_minute)


def split_time(seconds, per_minute):
    return divmod(seconds, per_minute)


def format_pair(minutes, seconds):
    return "{0}m {1:02d}s".format(minutes, seconds)


def playback(data):
    duration, multiplier = validate(data)
    faster = adjusted_duration(duration, multiplier)
    seconds = total_seconds(faster, SECONDS_PER_MINUTE)
    return split_time(seconds, SECONDS_PER_MINUTE)


def report(data):
    minutes, seconds = playback(data)
    original, multiplier = data
    clock = format_pair(minutes, seconds)
    head = "{0} min at {1}x".format(original, multiplier)
    return "{0} -> {1}".format(head, clock)


def main():
    samples = [
        [30, 1.5],
        [45, 2],
        [10, 0.5],
        [90, 1.25],
        [7, 3],
    ]
    for sample in samples:
        print(report(sample))


if __name__ == "__main__":
    main()

