import numbers

POINT_NAMES = ("regular", "style")


def total_score(regular_points, style_points):
    return regular_points + style_points / 10


def affirmative_wins(affirmative_total, negative_total):
    return affirmative_total > negative_total


def validate_team(label, points):
    if len(points) != 2:
        raise ValueError("{} team needs regular and style points".format(label))
    for index, value in enumerate(points):
        if not isinstance(value, numbers.Real):
            raise TypeError("{} {} points must be numeric".format(label, POINT_NAMES[index]))
        if value < 0:
            raise ValueError("{} {} points must not be negative".format(label, POINT_NAMES[index]))
    return points


def standings(scores):
    affirmative, negative = scores
    affirmative_points = validate_team("affirmative", affirmative)
    negative_points = validate_team("negative", negative)
    affirmative_regular, affirmative_style = affirmative_points
    negative_regular, negative_style = negative_points
    affirmative_total = total_score(affirmative_regular, affirmative_style)
    negative_total = total_score(negative_regular, negative_style)
    won = affirmative_wins(affirmative_total, negative_total)
    return affirmative_total, won


def parse_points(text):
    regular, style = text.split()
    return [float(regular), float(style)]


def parse_round(text):
    affirmative_text, negative_text = text.split("/")
    return [parse_points(affirmative_text), parse_points(negative_text)]


def format_result(scores):
    affirmative_total, won = standings(scores)
    negative_regular, negative_style = scores[1]
    negative_total = total_score(negative_regular, negative_style)
    winner = "affirmative" if won else "negative"
    header = "aff {:.1f} vs neg {:.1f}".format(affirmative_total, negative_total)
    return "{} -> {} takes the round".format(header, winner)


def summarize(rounds):
    lines = []
    victories = 0
    for round_scores in rounds:
        lines.append(format_result(round_scores))
        if standings(round_scores)[1]:
            victories += 1
    lines.append("affirmative won {} of {} rounds".format(victories, len(rounds)))
    return "\n".join(lines)


