def calculate_factorial(n):
    """Return n! for a non-negative integer n."""
    validate_input(n)
    result = 1
    for factor in range(2, n + 1):
        result *= factor
    return result


def validate_input(n):
    """Reject anything that is not a plain non-negative integer."""
    if isinstance(n, bool):
        raise TypeError("factorial requires a plain integer: {!r}".format(n))
    if not isinstance(n, int):
        raise TypeError("factorial requires an integer: {!r}".format(n))
    if n < 0:
        raise ValueError("factorial is undefined for negative input {}".format(n))


def factorial_table(values):
    return [(value, calculate_factorial(value)) for value in values]


def group_digits(number, separator=","):
    """Insert a separator every three digits from the right."""
    digits = str(number)
    chunks = []
    while len(digits) > 3:
        chunks.append(digits[-3:])
        digits = digits[:-3]
    chunks.append(digits)
    return separator.join(reversed(chunks))


def format_row(value, rendered):
    label = "{}!".format(value).rjust(4)
    return "{} = {}".format(label, rendered)


def render_table(rows):
    width = max(len(group_digits(pair[1])) for pair in rows)
    lines = []
    for value, factorial in rows:
        cell = group_digits(factorial).rjust(width)
        lines.append(format_row(value, cell))
    return lines


def describe_value(value):
    try:
        return format_row(value, group_digits(calculate_factorial(value)))
    except (TypeError, ValueError) as error:
        return "{!r} rejected: {}".format(value, error)


def main():
    wanted = [
        0,
        1,
        5,
        10,
        20,
    ]
    for line in render_table(factorial_table(wanted)):
        print(line)

    print("-" * 24)
    rejected = [
        -3,
        2.5,
        "7",
        True,
    ]
    for value in rejected:
        print(describe_value(value))


if __name__ == "__main__":
    main()

