MIN_YEAR = 1000
MAX_YEAR = 2200


def validate_years(birth_year, current_year):
    """Ensure both years are usable integers in a sensible calendar range."""
    labelled = [
        ("birth_year", birth_year),
        ("current_year", current_year),
    ]
    for label, value in labelled:
        if type(value) is not int:
            raise TypeError(f"{label} must be an integer, got {value!r}")
        if not MIN_YEAR <= value <= MAX_YEAR:
            raise ValueError(f"{label} must be between {MIN_YEAR} and {MAX_YEAR}")
    if current_year < birth_year:
        raise ValueError(f"current_year {current_year} precedes birth_year {birth_year}")


def calculate_age(birth_year, current_year):
    """Return the age in whole years of somebody born in birth_year."""
    validate_years(birth_year, current_year)
    return current_year - birth_year


def age_group(age):
    """Classify an age into a coarse life-stage label."""
    boundaries = [
        (3, "infant"),
        (13, "child"),
        (20, "teenager"),
        (65, "adult"),
    ]
    for limit, name in boundaries:
        if age < limit:
            return name
    return "senior"


def parse_record(line):
    """Turn 'Name, birth year' text into a (name, birth_year) pair."""
    parts = [field.strip() for field in line.split(",")]
    if len(parts) != 2:
        raise ValueError(f"expected 'name, year' but got {line!r}")
    name, raw_year = parts
    if not name:
        raise ValueError(f"missing name in {line!r}")
    return name, int(raw_year)


def build_report(records, current_year):
    """Compute age and group for each (name, birth_year) record."""
    report = []
    for name, birth_year in records:
        age = calculate_age(birth_year, current_year)
        report.append({
            "name": name,
            "age": age,
            "group": age_group(age),
        })
    return report


def format_report(report):
    """Render report rows as an aligned table of text lines."""
    width = max([len("NAME")] + [len(row["name"]) for row in report])
    lines = [f"{'NAME':<{width}}  {'AGE':>3}  GROUP"]
    for row in report:
        lines.append(f"{row['name']:<{width}}  {row['age']:>3}  {row['group']}")
    return lines


def main():
    current_year = 2023
    raw_records = [
        "Ada Lovelace, 1815",
        "Grace Hopper, 1906",
        "Alan Turing, 1912",
        "Newborn, 2023",
    ]
    records = [parse_record(line) for line in raw_records]
    report = build_report(records, current_year)
    for line in format_report(report):
        print(line)
    oldest = max(report, key=lambda row: row["age"])
    print(f"Oldest: {oldest['name']} at {oldest['age']}")


if __name__ == "__main__":
    main()

