def parse_csv_line(line):
    """Split a single CSV line into its comma-separated values."""
    if not isinstance(line, str):
        raise TypeError("line must be a string, got %r" % type(line).__name__)
    return line.rstrip("\r\n").split(",")


def parse_csv_text(text):
    """Parse a multi-line CSV document into a list of rows."""
    rows = []
    for raw in text.splitlines():
        if raw.strip():
            rows.append(parse_csv_line(raw))
    return rows


def normalize_rows(rows, width=None):
    """Pad or trim every row so that all rows share the same width."""
    if width is None:
        width = max((len(row) for row in rows), default=0)
    normalized = []
    for row in rows:
        cells = [cell.strip() for cell in row[:width]]
        cells.extend("" for _ in range(width - len(cells)))
        normalized.append(cells)
    return normalized


def convert_cell(cell):
    """Convert a cell to int or float when it looks numeric."""
    for converter in (int, float):
        try:
            return converter(cell)
        except ValueError:
            continue
    return cell


def rows_to_records(rows):
    """Use the first row as field names and build a dict per data row."""
    header, *body = normalize_rows(rows)
    return [dict(zip(header, [convert_cell(cell) for cell in row])) for row in body]


def column_widths(grid):
    """Measure the widest cell in each column."""
    return [max(len(row[index]) for row in grid) for index in range(len(grid[0]))]


def format_table(rows):
    """Render rows as a fixed-width text table."""
    grid = normalize_rows(rows)
    widths = column_widths(grid)
    lines = []
    for row in grid:
        padded = [cell.ljust(widths[index]) for index, cell in enumerate(row)]
        lines.append("  ".join(padded))
    return "\n".join(lines)


def column_sum(records, field):
    """Total a numeric column across parsed records."""
    numbers = (int, float)
    return sum(record[field] for record in records if isinstance(record[field], numbers))


def main():
    print(parse_csv_line("apple,banana,cherry"))
    print(parse_csv_line("1,2,3"))

    document = "\n".join([
        "name,quantity,price",
        "apple, 12, 0.50",
        "banana, 6, 0.25",
        "cherry, 30, 1.75",
    ])
    rows = parse_csv_text(document)
    print(format_table(rows))

    records = rows_to_records(rows)
    for record in records:
        print("{name}: {quantity} @ {price}".format(**record))

    for field in ("quantity", "price"):
        total = column_sum(records, field)
        print("total %s = %s" % (field, total))


if __name__ == "__main__":
    main()

