def normalize(text):
    """Return the text folded to lower case with blank characters removed."""
    if not isinstance(text, str):
        raise TypeError("text must be a string, got " + type(text).__name__)
    return "".join(ch for ch in text.lower() if not ch.isspace())


def count_chars(text):
    """Map every character of the normalized text to how often it occurs."""
    counts = {}
    for ch in normalize(text):
        counts[ch] = counts.get(ch, 0) + 1
    return counts


def most_frequent_char(text):
    """Return the most frequent character, earliest appearance breaking ties."""
    counts = count_chars(text)
    if not counts:
        return None
    best = None
    for ch, total in counts.items():
        if best is None or total > counts[best]:
            best = ch
    return best


def ranked_chars(text, limit=None):
    """Return (character, count) pairs ordered by decreasing count."""
    counts = count_chars(text)
    order = {}
    for index, ch in enumerate(counts):
        order[ch] = index
    def rank_key(item):
        character = item[0]
        return -item[1], order[character]
    ranking = sorted(counts.items(), key=rank_key)
    if limit is None:
        return ranking
    return ranking[:limit]


def format_report(text, limit=3):
    """Build a short human readable summary of the character frequencies."""
    counts = count_chars(text)
    winner = most_frequent_char(text)
    if winner is None:
        return "%r -> nothing to count" % (text,)
    parts = []
    for item in ranked_chars(text, limit):
        parts.append("%s:%d" % item)
    head = "{0!r} -> {1!r}".format(text, winner)
    distinct = len(counts)
    counted = sum(counts.values())
    body = "({0} distinct, {1} counted)".format(distinct, counted)
    return head + " " + body + " [" + " ".join(parts) + "]"


def main():
