def is_leap_year(year):
    """Return True if `year` is a leap year in the Gregorian calendar."""
    if not isinstance(year, int):
        raise TypeError("year must be a whole number of years")
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    return year % 4 == 0


MONTHS = [
    ("January", 31),
    ("February", 28),
    ("March", 31),
    ("April", 30),
    ("May", 31),
    ("June", 30),
    ("July", 31),
    ("August", 31),
    ("September", 30),
    ("October", 31),
    ("November", 30),
    ("December", 31),
]


def month_entry(month):
    """Return the (name, common-year length) pair for `month` (1-12)."""
    if month not in range(1, 13):
        raise ValueError("month must be in 1..12")
    return MONTHS[month - 1]


def days_in_month(year, month):
    """Return the number of days in `month` of `year`."""
    length = month_entry(month)[1]
    if month == 2 and is_leap_year(year):
        return 29
    return length


def days_in_year(year):
    """Return 366 for a leap year and 365 otherwise."""
    return 366 if is_leap_year(year) else 365


def quarter_months(quarter):
    """Return the three month numbers belonging to `quarter` (1-4)."""
    first = 3 * (quarter - 1) + 1
    return list(range(first, first + 3))


def days_in_quarter(year, quarter):
    """Return the total number of days in the given quarter of `year`."""
    return sum(days_in_month(year, month) for month in quarter_months(quarter))


def leap_years_between(start, end):
    """Return the leap years in the inclusive range between the two bounds."""
    if start > end:
        return leap_years_between(end, start)
    return [year for year in range(start, end + 1) if is_leap_year(year)]


def format_row(year):
    """Describe one year: its February length and whether it is a leap year."""
    kind = "leap" if is_leap_year(year) else "common"
    return "{:>6}  {:>2} days in {:<9} {}".format(
        year,
        days_in_month(year, 2),
        month_entry(2)[0],
        kind,
    )


def format_report(years):
    """Build a table of February lengths for the given years."""
    lines = ["  Year  February            Kind"]
    for year in years:
        lines.append(format_row(year))
    return "\n".join(lines)


def main():
    samples = [
        1900,
        1996,
        2000,
        2023,
        2024,
        2100,
    ]
    print(format_report(samples))
    print()
    for year in samples:
        print("%d has %d days" % (year, days_in_year(year)))
    print()
    span = leap_years_between(1890, 1920)
    print("Leap years 1890-1920: " + ", ".join(str(year) for year in span))
    for quarter in range(1, 5):
        opening = month_entry(quarter_months(quarter)[0])[0]
        total = days_in_quarter(2024, quarter)
        print("2024 quarter starting %s: %d days" % (opening, total))


if __name__ == "__main__":
    main()

