"""Detect clashes between a proposed event and an existing schedule."""


def validate_interval(start, end):
    """Return the interval as a tuple, rejecting bad types or empty spans."""
    for value in (start, end):
        if not isinstance(value, int):
            raise TypeError("event times must be integers: {!r}".format(value))
    if start >= end:
        raise ValueError("event must start before it ends: {!r}".format((start, end)))
    return start, end


def normalize_schedule(schedule):
    """Validate every entry of a schedule and return it sorted by start time."""
    cleaned = []
    for entry in schedule:
        start, end = entry
        cleaned.append(validate_interval(start, end))
    cleaned.sort()
    return cleaned


def conflicting_events(schedule, event):
    """List the already scheduled events that clash with the given event."""
    start, end = event
    validate_interval(start, end)
    existing = normalize_schedule(schedule)
    return [other for other in existing if other[0] < end and start < other[1]]


def has_conflict(
    schedule,
    new_event_start,
    new_event_end,
):
    """Return True when the new event overlaps an event already scheduled."""
    new_event = validate_interval(new_event_start, new_event_end)
    return bool(conflicting_events(schedule, new_event))


def format_schedule(schedule):
    parts = []
    for start, end in schedule:
        parts.append("{}-{}".format(start, end))
    return ", ".join(parts)


def insert_event(schedule, event):
    clashes = conflicting_events(schedule, event)
    if clashes:
        wanted = format_schedule([event])
        raise ValueError("cannot insert " + wanted + " over " + format_schedule(clashes))
    events = list(schedule)
    events.append(event)
    return normalize_schedule(events)


def report(schedule, requests):
    lines = []
    current = normalize_schedule(schedule)
    for event in requests:
        clashes = conflicting_events(current, event)
        label = format_schedule([event])
        if clashes:
            lines.append("REJECT " + label + " clashes with " + format_schedule(clashes))
        else:
            current = insert_event(current, event)
            lines.append("ACCEPT " + label)
    lines.append("final schedule: " + format_schedule(current))
    return lines


def main():
    schedule = [
        (1, 5),
        (10, 15),
    ]
    requests = [
        (3, 7),
        (6, 8),
        (15, 18),
        (14, 16),
    ]
    for line in report(schedule, requests):
        print(line)


if __name__ == "__main__":
    main()

