def split_words(sentence):
    """Return the list of words in a sentence."""
    return sentence.split()


def word_lengths(sentence):
    """Return the length of each word in a sentence."""
    return [len(word) for word in split_words(sentence)]


def reverse_words(sentence):
    """Reverse the word order of a sentence and keep each word intact."""
    if not isinstance(sentence, str):
        raise TypeError('expected str but got ' + type(sentence).__name__)
    return ' '.join(reversed(split_words(sentence)))


def word_stats(sentence):
    """Summarise a sentence with its word count and word length extremes."""
    lengths = word_lengths(sentence)
    return {
        'words': len(lengths),
        'letters': sum(lengths),
        'shortest': min(lengths, default=0),
        'longest': max(lengths, default=0),
    }


def is_palindromic_order(sentence):
    """True when a sentence reads the same word by word in both directions."""
    words = split_words(sentence)
    return words == words[::-1]


def format_stats(stats):
    """Render the statistics of a sentence as a compact text block."""
    return 'words={} letters={} shortest={} longest={}'.format(
        stats['words'], stats['letters'],
        stats['shortest'], stats['longest'],
    )


def format_report(sentence, stats):
    """Build a one line readable report about a sentence."""
    return '{!r} -> {!r} | {} | symmetric={}'.format(
        sentence, reverse_words(sentence),
        format_stats(stats),
        'yes' if is_palindromic_order(sentence) else 'no',
    )


def report_lines(samples):
    """Build one report line per sentence."""
    return [format_report(sample, word_stats(sample)) for sample in samples]


def main():
    """Print a report for a few sentences."""
    samples = [
        'hello world',
        'Python is fun',
        '  keep    the   words  intact  ',
        'never odd or even odd never',
    ]
    for line in report_lines(samples):
        print(line)


if __name__ == '__main__':
    main()

