def is_armstrong(number):
    if not isinstance(number, int) or number <= 0:
        raise ValueError("Input must be a positive integer, got {}".format(number))

    number_str = str(number)
    num_digits = len(number_str)

    sum_of_powers = 0
    for digit_char in number_str:
        digit = int(digit_char)
        sum_of_powers += digit ** num_digits

    return sum_of_powers == number

tests = [
    (153, True), (9, True), (10, False), (370, True), (371, True),
    (407, True), (1634, True), (8208, True), (9474, True), (123, False)
]

for num, expected in tests:
    actual = is_armstrong(num)
    assert actual == expected, f"For number {num}, expected {expected}, but got {actual}"

edge_cases = [
    (1, True), (2, True), (3, True), (4, True), (5, True),
    (6, True), (7, True), (8, True)
]

for num, expected in edge_cases:
    actual = is_armstrong(num)
    assert actual == expected, f"For single digit {num}, expected {expected}, got {actual}"

invalid_inputs = [
    (0, "Input must be a positive integer"), (-5, "Input must be a positive integer"),
    (1.5, "Input must be a positive integer"), ("abc", "Input must be a positive integer")
]

for bad_input, error_msg_part in invalid_inputs:
    try:
        is_armstrong(bad_input)
        assert False, f"Expected ValueError for {bad_input}, but no error was raised"
    except ValueError as e:
        assert error_msg_part in str(e), f"Expected '{error_msg_part}' in error message, got '{e}'"

