NUMBER_TYPES = (int, float)

COLUMNS = [
    "   width",
    "  height",
    "      area",
    " perimeter",
    "  diagonal",
    "sq?",
]

HEADER = " | ".join(COLUMNS)


def _validate(name, value):
    if isinstance(value, bool):
        raise TypeError(name + " must be a number and not a boolean")
    if not isinstance(value, NUMBER_TYPES):
        kind = type(value).__name__
        raise TypeError("{} must be a number: got {}".format(name, kind))
    if value <= 0:
        raise ValueError("{} must be positive: got {}".format(name, value))
    return float(value)


def rectangle_area(width, height):
    w = _validate("width", width)
    h = _validate("height", height)
    return w * h


def rectangle_perimeter(width, height):
    w = _validate("width", width)
    h = _validate("height", height)
    return 2.0 * (w + h)


def rectangle_diagonal(width, height):
    w = _validate("width", width)
    h = _validate("height", height)
    return (w * w + h * h) ** 0.5


def describe(width, height):
    w = _validate("width", width)
    h = _validate("height", height)
    return {
        "width": w,
        "height": h,
        "area": rectangle_area(w, h),
        "perimeter": rectangle_perimeter(w, h),
        "diagonal": rectangle_diagonal(w, h),
        "square": abs(w - h) < 1e-9,
    }


def format_row(info):
    cells = [
        "{:>8.2f}".format(info["width"]),
        "{:>8.2f}".format(info["height"]),
        "{:>10.2f}".format(info["area"]),
        "{:>10.2f}".format(info["perimeter"]),
        "{:>10.3f}".format(info["diagonal"]),
        "yes" if info["square"] else "no",
    ]
    return " | ".join(cells)


def format_table(pairs):
    lines = [HEADER, "-" * len(HEADER)]
    for width, height in pairs:
        lines.append(format_row(describe(width, height)))
    return "\n".join(lines)


def total_area(pairs):
    total = 0.0
    for width, height in pairs:
        total += rectangle_area(width, height)
    return total


def main():
    pairs = [
        (5, 10),
        (2.5, 4),
        (3, 3),
        (12.75, 0.5),
    ]
    print(format_table(pairs))
    print("total area: {:.2f}".format(total_area(pairs)))
    rejected = [
        (0, 5),
        (-1, 2),
        ("4", 4),
    ]
    for width, height in rejected:
        try:
            rectangle_area(width, height)
        except (TypeError, ValueError) as exc:
            print("rejected: {}".format(exc))


if __name__ == "__main__":
    main()

