def get_item_quantity(inventory, item_name):
    """Return the quantity of item_name in inventory, or 0 if absent."""
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict of names to quantities")
    if not isinstance(item_name, str):
        raise TypeError("item_name must be a str")
    return int(inventory.get(item_name, 0))


def add_stock(inventory, entry):
    """Apply a (name, amount) delivery entry and return the new quantity."""
    name, amount = entry
    if amount < 0:
        raise ValueError("delivered amount must not be negative")
    quantity = get_item_quantity(inventory, name) + amount
    inventory[name] = quantity
    return quantity


def remove_stock(inventory, request):
    """Take units out of stock for a (name, amount) request, never below zero."""
    name, amount = request
    available = get_item_quantity(inventory, name)
    taken = min(available, amount)
    remaining = available - taken
    if remaining:
        inventory[name] = remaining
    else:
        inventory.pop(name, None)
    return taken


def total_units(inventory, item_names):
    """Sum the quantities of the given item names."""
    return sum(get_item_quantity(inventory, name) for name in item_names)


def low_stock(inventory, threshold):
    """Names of items at or below threshold, ordered by quantity then name."""
    candidates = [name for name in inventory if inventory[name] <= threshold]
    return sorted(
        candidates,
        key=lambda name: (inventory[name], name),
    )


def format_report(inventory, item_names):
    """Build aligned "name : quantity" lines for the requested items."""
    width = max((len(name) for name in item_names), default=0)
    lines = []
    for name in item_names:
        quantity = get_item_quantity(inventory, name)
        lines.append(f"{name:<{width}} : {quantity:>4}")
    return "\n".join(lines)


def main():
    inventory = {'apple': 10, 'banana': 5,
                 'cherry': 2, 'date': 0}
    queried = ['apple', 'banana',
               'orange', 'cherry']
    print(format_report(inventory, queried))
    total = total_units(inventory, queried)
    print("total queried units:", total)

    deliveries = [('orange', 12),
                  ('banana', 3)]
    for entry in deliveries:
        add_stock(inventory, entry)

    request = ('cherry', 5)
    taken = remove_stock(inventory, request)
    left = get_item_quantity(inventory, 'cherry')
    print(f"took {taken} cherry, {left} left")

    for name in low_stock(inventory, 4):
        quantity = get_item_quantity(inventory, name)
        print(f"restock needed: {name} {quantity}")

    print(format_report(inventory, sorted(inventory)))
    print(get_item_quantity(inventory, 'apple'))
    print(get_item_quantity(inventory, 'kiwi'))


if __name__ == '__main__':
    main()

