import math

SEQUENCE_TYPES = (list, tuple)
NUMBER_TYPES = (int, float)


def parse_token(token):
    """Convert one text token into an int when possible, otherwise a float."""
    try:
        return int(token)
    except ValueError:
        return float(token)


def parse_numbers(text):
    """Turn a text line of numeric tokens into a list of values."""
    return [parse_token(token) for token in text.split()]


def validate_numbers(numbers):
    """Return the input as a list of numbers, raising on invalid content."""
    if not isinstance(numbers, SEQUENCE_TYPES):
        raise TypeError("numbers must be a list or tuple")
    values = list(numbers)
    if len(values) < 2:
        raise ValueError("numbers must contain at least two elements")
    for value in values:
        if not isinstance(value, NUMBER_TYPES):
            raise TypeError("all elements must be int or float")
        if isinstance(value, float) and not math.isfinite(value):
            raise ValueError("numbers must be finite")
    if len(set(values)) < 2:
        raise ValueError("numbers must contain at least two distinct values")
    return values


def find_second_smallest(numbers):
    """Return the second smallest distinct value in numbers."""
    values = validate_numbers(numbers)
    smallest = math.inf
    second = math.inf
    for value in values:
        if value < smallest:
            second = smallest
            smallest = value
        elif smallest < value < second:
            second = value
    return second


def summarize(numbers):
    """Build a small report dictionary describing the extremes of numbers."""
    values = validate_numbers(numbers)
    ordered = sorted(set(values))
    return {
        "count": len(values),
        "distinct": len(ordered),
        "smallest": ordered[0],
        "second_smallest": find_second_smallest(values),
        "largest": ordered[-1],
    }


def format_number(value):
    """Render a number compactly, trimming trailing zeros from floats."""
    if isinstance(value, int):
        return str(value)
    text = "{0:.6f}".format(value).rstrip("0").rstrip(".")
    return text if text not in ("", "-") else "0"


def format_report(numbers):
    """Produce a one-line human readable summary of a list of numbers."""
    info = summarize(numbers)
    fields = [
        "n={0}".format(info["count"]),
        "distinct={0}".format(info["distinct"]),
        "min={0}".format(format_number(info["smallest"])),
        "2nd={0}".format(format_number(info["second_smallest"])),
        "max={0}".format(format_number(info["largest"])),
    ]
    return " | ".join(fields)


def main():
    datasets = [
        "5 1 8 2 9",
        "10 20 30 5",
        "3.5 -2.25 0 7 -2.25",
        "100 100 99",
    ]
    for text in datasets:
        values = parse_numbers(text)
        print("input:", text)
        print("  second smallest:", format_number(find_second_smallest(values)))
        print("  report:", format_report(values))


if __name__ == "__main__":
    main()

