def parse_csv_line(csv_line):
    """Split one line of unquoted CSV data into a list of field strings."""
    if not isinstance(csv_line, str):
        raise TypeError("csv_line must be a str")
    return csv_line.rstrip("\r\n").split(",")

def clean_fields(fields):
    """Return each field without its surrounding blanks."""
    return [field.strip() for field in fields]

def classify_field(field):
    """Return a short type name for a raw CSV field."""
    if field == "":
        return "empty"
    if field.lstrip("+-").isdigit():
        return "int"
    try:
        float(field)
    except ValueError:
        return "text"
    return "float"

