import math


def euclidean_distance_2d(x1: float, y1: float,
                          x2: float, y2: float) -> float:
    """Return the straight-line distance between the two given points."""
    dx = float(x2) - float(x1)
    dy = float(y2) - float(y1)
    return math.hypot(dx, dy)


def parse_point(text):
    """Parse a point written as '(x, y)' or as 'x y' into a pair of floats."""
    cleaned = text.strip().strip("()")
    parts = cleaned.replace(",", " ").split()
    if len(parts) != 2:
        raise ValueError("expected two coordinates in " + repr(text))
    return float(parts[0]), float(parts[1])


def path_length(points):
    """Total length of the polyline running through a sequence of points."""
    total = 0.0
    for index in range(len(points) - 1):
        total += euclidean_distance_2d(*points[index], *points[index + 1])
    return total


def closest_pair(points):
    """Return the two points of the sequence that lie closest together."""
    if len(points) < 2:
        raise ValueError("need at least two points")
    best_pair = None
    best_distance = math.inf
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            d = euclidean_distance_2d(*points[i], *points[j])
            if d < best_distance:
                best_distance = d
                best_pair = (points[i], points[j])
    return best_pair


def format_point(point):
    """Render a point in the usual parenthesised notation."""
    return "({:g}, {:g})".format(*point)


def format_distance(start, end):
    """Describe the distance between two points on a single line."""
    d = euclidean_distance_2d(*start, *end)
    return f"{format_point(start)} -> {format_point(end)} = {d:.4f}"


def main():
    route = [
        parse_point("0, 0"),
        parse_point("(3, 4)"),
        parse_point("3 0"),
        parse_point("-1 -1"),
    ]
    print(format_distance(route[0], route[1]))
    print("path length = {:.4f}".format(path_length(route)))
    print("closest: " + format_distance(*closest_pair(route)))


if __name__ == "__main__":
    main()

