"""Helpers for filtering numeric mappings by a threshold value."""

NUMERIC_TYPES = (int, float)


def check_numeric(value, label):
    """Raise TypeError unless value is a plain int or float."""
    if isinstance(value, bool):
        raise TypeError("%s must not be a boolean" % label)
    if not isinstance(value, NUMERIC_TYPES):
        raise TypeError("%s must be an int or a float" % label)


def filter_dict_by_value(input_dict, threshold):
    """Return the pairs of input_dict whose value is strictly greater than threshold."""
    if not isinstance(input_dict, dict):
        raise TypeError("input_dict must be a dict, got %s" % type(input_dict).__name__)
    check_numeric(threshold, "threshold")
    result = {}
    for key, value in input_dict.items():
        check_numeric(value, "value for key %r" % (key,))
        if value > threshold:
            result[key] = value
    return result


def format_dict(mapping):
    """Render a mapping as a compact sorted string."""
    parts = ["%r: %s" % (key, mapping[key]) for key in sorted(mapping)]
    return "{" + ", ".join(parts) + "}"


def rank(item):
    """Order a key/value pair by descending value, then by key."""
    return -item[1], item[0]


def top_values(kept, count):
    """Return the highest-valued pairs of kept, at most count of them."""
    return sorted(kept.items(), key=rank)[:count]


def summarize(input_dict, threshold):
    """Build a one-line report about the filtering of input_dict."""
    above = filter_dict_by_value(input_dict, threshold)
    dropped = len(input_dict) - len(above)
    report = f"threshold={threshold} kept={len(above)} dropped={dropped}"
    return f"{report} result={format_dict(above)}"


def main():
    inventory = {
        'bolts': 120,
        'nuts': 45,
        'washers': 8,
        'screws': 240,
        'nails': 15,
    }
    scores = {
        'a': 10,
        'b': 20,
        'c': 5,
    }
    tiny = {'x': 1, 'y': 2}
    print(format_dict(filter_dict_by_value(scores, 15)))
    print(format_dict(filter_dict_by_value(tiny, 5)))
    for threshold in (10, 50):
        print(summarize(inventory, threshold))
    kept = filter_dict_by_value(inventory, 10)
    print("top picks:")
    for item in top_values(kept, 3):
        print("  %-8s %5d" % item)


if __name__ == "__main__":
    main()

