def is_valid_ipv4(ip_address):
    octets = ip_address.split('.')

    if len(octets) != 4:
        return False

    for octet_str in octets:
        if not octet_str.isdigit():
            return False

        octet = int(octet_str)
        if not (0 <= octet <= 255):
            return False

        if len(octet_str) > 1 and octet_str[0] == '0':
            return False 

    return True

