def is_prime(number):
    """Return True when `number` is a prime, using trial division."""
    if number < 2:
        return False
    if number in (2, 3):
        return True
    if number % 2 == 0:
        return False
    divisor = 3
    while divisor * divisor <= number:
        if number % divisor == 0:
            return False
        divisor += 2
    return True


def generate_primes(n):
    """Return every prime up to and including `n`."""
    if isinstance(n, bool):
        raise TypeError("n must be a plain integer")
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    return [candidate for candidate in range(2, n + 1) if is_prime(candidate)]


def twin_pairs(primes):
    """Pair consecutive primes that differ by exactly two."""
    pairs = []
    for index in range(len(primes) - 1):
        left = primes[index]
        right = primes[index + 1]
        if right - left == 2:
            pairs.append((left, right))
    return pairs


def largest_gap(primes):
    """Return the widest distance between two consecutive primes."""
    gap = 0
    for index in range(1, len(primes)):
        gap = max(gap, primes[index] - primes[index - 1])
    return gap


FIELD_ORDER = (
    "count",
    "total",
    "largest",
    "gap",
    "twins",
)


def prime_summary(n):
    """Collect a few statistics about the primes below or equal to `n`."""
    primes = generate_primes(n)
    return {
        "count": len(primes),
        "total": sum(primes),
        "largest": primes[-1] if primes else 0,
        "gap": largest_gap(primes),
        "twins": len(twin_pairs(primes)),
    }


def format_summary(n):
    """Build a one-line human readable report for the limit `n`."""
    summary = prime_summary(n)
    parts = ["limit=%d" % n]
    for name in FIELD_ORDER:
        parts.append("%s=%d" % (name, summary[name]))
    return " | ".join(parts)


def main():
    print("primes up to 10:", generate_primes(10))
    print("primes up to 2:", generate_primes(2))
    for limit in (50, 100):
        print(format_summary(limit))
    print("twins up to 60:", twin_pairs(generate_primes(60)))


if __name__ == "__main__":
    main()

