def binary_to_decimal(binary_string):
    decimal_value, power_of_two = 0, 0
    for digit in reversed(binary_string):
        if digit == '1':
            decimal_value += 2 ** power_of_two
        power_of_two += 1
    return decimal_value

test_cases, results = ['1', '10', '11', '100', '101'], [1, 2, 3, 4, 5]
for index, binary_str in enumerate(test_cases):
    expected, actual = results[index], binary_to_decimal(binary_str)
    assert actual == expected, f"Input: {binary_str}, Expected: {expected}, Got: {actual}"

more_tests, outcomes = ['111', '1000', '1001', '1010', '1011', '1100'], [7, 8, 9, 10, 11, 12]
for idx, bin_str in enumerate(more_tests):
    expected_val, actual_val = outcomes[idx], binary_to_decimal(bin_str)
    assert actual_val == expected_val, f"Test: {bin_str}, Expected: {expected_val}, Actual: {actual_val}"

final_tests, expected_final = ['0', '1111', '10000', '11111'], [0, 15, 16, 31]
for i, b_str in enumerate(final_tests):
    exp, act = expected_final[i], binary_to_decimal(b_str)
    assert act == exp, f"Final check: {b_str}, Exp: {exp}, Act: {act}"

print("All tests passed, including edge cases, long strings, and zero.")

