from collections import OrderedDict

PAIR_SEPARATOR = ", "


def _fallback_key(key):
    """Sort key used when keys of mixed types cannot be compared directly."""
    return (type(key).__name__, repr(key))


def sort_dict_by_key(input_dict):
    """Return a new OrderedDict holding the items of input_dict sorted by key."""
    if not isinstance(input_dict, dict):
        raise TypeError("sort_dict_by_key expects a dict, got %s" % type(input_dict).__name__)
    try:
        ordered_keys = sorted(input_dict)
    except TypeError:
        ordered_keys = sorted(input_dict, key=_fallback_key)
    return OrderedDict((key, input_dict[key]) for key in ordered_keys)


def merge_sorted(*dicts):
    """Merge several dictionaries and return the result sorted by key."""
    combined = {}
    for source in dicts:
        combined.update(source)
    return sort_dict_by_key(combined)


def _render_pair(key, value):
    return "%r: %r" % (key, value)


def format_dict(mapping, separator=PAIR_SEPARATOR):
    """Render a mapping as a single readable line."""
    pairs = [_render_pair(key, mapping[key]) for key in mapping]
    return "{" + separator.join(pairs) + "}"


def describe(mapping):
    """Build a small report about a mapping and the order of its keys."""
    ordered = sort_dict_by_key(mapping)
    return {
        "size": len(ordered),
        "keys": list(ordered.keys()),
        "values": list(ordered.values()),
        "already_sorted": list(mapping.keys()) == list(ordered.keys()),
        "rendered": format_dict(ordered),
    }


def report_lines(mapping):
    """Yield the lines of a human readable report for one mapping."""
    info = describe(mapping)
    yield "input    : %s" % format_dict(mapping)
    yield "sorted   : %s" % info["rendered"]
    yield "keys     : %s" % ", ".join(str(key) for key in info["keys"])
    yield "size     : %d (untouched: %s)" % (info["size"], info["already_sorted"])


def main():
    examples = [
        {
            'b': 2,
            'a': 1,
            'c': 3,
        },
        {'z': 26, 'y': 25},
        {3: 'three', 1: 'one'},
    ]
    for sample in examples:
        for line in report_lines(sample):
            print(line)
        print("-" * 40)

    inventory = merge_sorted(
        {'pears': 4, 'apples': 12},
        {'bananas': 7, 'apples': 3},
        {'cherries': 20},
    )
    print("merged   : %s" % format_dict(inventory))
    print("total    : %d" % sum(inventory.values()))
    print("piped    : %s" % format_dict(inventory, separator=" | "))


if __name__ == "__main__":
    main()

