NUMERIC_TYPES = (int, float)


class BankAccount:
    """A bank account tracking a balance and a signed transaction log."""

    def __init__(self, initial_balance=0):
        if not isinstance(initial_balance, NUMERIC_TYPES):
            raise TypeError("initial_balance must be a number")
        if initial_balance < 0:
            raise ValueError("initial_balance must not be negative")
        self.balance = initial_balance
        self.history = [("open", initial_balance)]

    def _is_valid(self, amount):
        return isinstance(amount, NUMERIC_TYPES) and amount > 0

    def deposit(self, amount):
        if not self._is_valid(amount):
            return False
        self.balance += amount
        self.history.append(("deposit", amount))
        return True

    def withdraw(self, amount):
        if not self._is_valid(amount) or amount > self.balance:
            return False
        self.balance -= amount
        self.history.append(("withdraw", -amount))
        return True

    def statement(self):
        columns = (
            "ACTION",
            "AMOUNT",
            "BALANCE",
        )
        rows = ["{:<10}{:>12}{:>12}".format(*columns)]
        running = 0.0
        for action, amount in self.history:
            running += amount
            figures = "{:>12.2f}{:>12.2f}".format(amount, running)
            rows.append("{:<10}{}".format(action, figures))
        return "\n".join(rows)


def replay(account, operations):
    """Apply (kind, amount) pairs, returning (label, accepted) outcomes."""
    results = []
    for kind, amount in operations:
        method = {"deposit": account.deposit, "withdraw": account.withdraw}.get(kind)
        if method is None:
            raise ValueError("unknown operation: {!r}".format(kind))
        label = "{} {:.2f}".format(kind, amount)
        results.append((label, method(amount)))
    return results


def summarize(results):
    accepted = sum(1 for entry in results if entry[1])
    return accepted, len(results) - accepted


def main():
    checking = BankAccount(100)
    plan = [
        ("deposit", 50),
        ("withdraw", 200),
        ("withdraw", 25),
        ("deposit", -5),
    ]
    outcomes = replay(checking, plan)
    for label, accepted in outcomes:
        print("{:<18} -> {}".format(label, accepted))

    taken, rejected = summarize(outcomes)
    print("accepted={} rejected={}".format(taken, rejected))
    print("final balance: {:.2f}".format(checking.balance))
    print(checking.statement())


if __name__ == "__main__":
    main()

