import math
import numbers


def _validate_point(point, name):
    allowed = (tuple, list)
    if not isinstance(point, allowed):
        raise TypeError(name + " must be a tuple or a list")
    if len(point) != 3:
        raise ValueError(name + " must have exactly three coordinates")
    coords = []
    for value in point:
        if not isinstance(value, numbers.Real):
            raise TypeError(name + " coordinates must be real numbers")
        coords.append(float(value))
    return tuple(coords)


def distance_3d(p1, p2):
    a = _validate_point(p1, 'p1')
    b = _validate_point(p2, 'p2')
    total = 0.0
    for index in range(3):
        total += (b[index] - a[index]) ** 2
    return math.sqrt(total)


def midpoint_3d(p1, p2):
    a = _validate_point(p1, 'p1')
    b = _validate_point(p2, 'p2')
    return tuple((a[index] + b[index]) / 2 for index in range(3))


def path_length(points):
    total = 0.0
    for index in range(1, len(points)):
        total += distance_3d(points[index - 1], points[index])
    return total


def closest_pair(points):
    if len(points) < 2:
        raise ValueError("need at least two points")
    best_left = 0
    best_right = 1
    best_gap = distance_3d(points[0], points[1])
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            gap = distance_3d(points[i], points[j])
            if gap < best_gap:
                best_gap = gap
                best_left = i
                best_right = j
    return best_left, best_right


def parse_point(text):
    parts = text.split(",")
    if len(parts) != 3:
        raise ValueError("expected three comma-separated coordinates")
    return tuple(float(part.strip()) for part in parts)


def format_point(point):
    coords = _validate_point(point, 'point')
    parts = ["{:g}".format(value) for value in coords]
    return "(" + ", ".join(parts) + ")"


def report_pair(p1, p2):
    head = format_point(p1) + " -> " + format_point(p2)
    detail = "d = {:.5f}".format(distance_3d(p1, p2))
    return head + " | " + detail + " | mid = " + format_point(midpoint_3d(p1, p2))


def main():
    print(report_pair(parse_point("0,0,0"), parse_point("1,1,1")))
    print(report_pair(parse_point("1,2,3"), parse_point("1,2,4")))
    route_text = [
        "0,0,0",
        "3,4,0",
        "3,4,12",
        "0,0,12",
    ]
    route = [parse_point(text) for text in route_text]
    print("path length: " + "{:.5f}".format(path_length(route)))
    left, right = closest_pair(route)
    gap = distance_3d(route[left], route[right])
    label = format_point(route[left]) + " and " + format_point(route[right])
    print("closest pair: " + label)
    print("smallest gap: " + "{:.5f}".format(gap))


if __name__ == '__main__':
    main()

