import random

LOW = 1
HIGH = 100


def require_int(value, name):
    if type(value) is not int:
        raise TypeError("{} must be an integer".format(name))


def validate_parameters(target, max_guesses):
    """Check that a game can actually be played with these settings."""
    require_int(target, "target")
    require_int(max_guesses, "max_guesses")
    if not LOW <= target <= HIGH:
        raise ValueError("target must lie between {} and {}".format(LOW, HIGH))
    if max_guesses < 0:
        raise ValueError("max_guesses must not be negative")


def play_guessing_game(target, max_guesses):
    """Guess randomly until target is hit; return attempts used or -1."""
    validate_parameters(target, max_guesses)
    for attempt in range(1, max_guesses + 1):
        if random.randint(LOW, HIGH) == target:
            return attempt
    return -1


def run_trials(experiment, trials):
    target, max_guesses = experiment
    return [play_guessing_game(target, max_guesses) for _ in range(trials)]


def summarize(results):
    """Turn raw outcomes into a success rate and average winning length."""
    wins = [r for r in results if r != -1]
    total = len(results)
    return {
        "trials": total,
        "wins": len(wins),
        "rate": len(wins) / total if total else 0.0,
        "average": sum(wins) / len(wins) if wins else 0.0,
    }


def theoretical_rate(max_guesses):
    span = HIGH - LOW + 1
    return 1.0 - ((span - 1) / span) ** max_guesses


def format_summary(experiment, stats):
    target, max_guesses = experiment
    return "target={:>3} budget={:>3} wins={:>5}/{:<5} rate={:>6.1%} expected={:>6.1%} avg={:>5.2f}".format(
        target, max_guesses,
        stats["wins"], stats["trials"],
        stats["rate"], theoretical_rate(max_guesses),
        stats["average"],
    )


def main():
    random.seed(2026)
    experiments = [
        (50, 10),
        (99, 1),
        (7, 50),
        (100, 200),
        (23, 100),
    ]
    trials = 2000
    print("guessing game simulation over {} trials".format(trials))
    for experiment in experiments:
        results = run_trials(experiment, trials)
        print(format_summary(experiment, summarize(results)))


if __name__ == "__main__":
    main()

