from math import sqrt


def is_valid_triangle(a, b, c):
    """Return True when the three lengths can form a non-degenerate triangle."""
    sides = sorted([a, b, c])
    if sides[0] <= 0:
        return False
    return sides[0] + sides[1] > sides[2]


def triangle_area(a, b, c):
    """Area of the triangle with sides a, b, c via Heron's formula (0.0 if invalid)."""
    if not is_valid_triangle(a, b, c):
        return 0.0
    s = (a + b + c) / 2.0
    return sqrt(s * (s - a) * (s - b) * (s - c))


def classify(a, b, c):
    """Describe the triangle by side equality, or 'degenerate' when impossible."""
    if not is_valid_triangle(a, b, c):
        return "degenerate"
    sides = sorted([a, b, c])
    if sides[0] == sides[2]:
        return "equilateral"
    if sides[0] == sides[1] or sides[1] == sides[2]:
        return "isosceles"
    return "scalene"


def angle_kind(a, b, c):
    """Return 'right', 'acute' or 'obtuse' using the squares of the sides."""
    if not is_valid_triangle(a, b, c):
        return "degenerate"
    sides = sorted([a, b, c])
    longest = sides[2] ** 2
    others = sides[0] ** 2 + sides[1] ** 2
    if abs(longest - others) < 1e-9:
        return "right"
    return "acute" if longest < others else "obtuse"


def describe(a, b, c):
    """Build a one-line summary of the triangle with the given sides."""
    area = triangle_area(a, b, c)
    if area == 0.0:
        return "sides %g, %g, %g: no triangle" % (a, b, c)
    perimeter = a + b + c
    shape = classify(a, b, c)
    angles = angle_kind(a, b, c)
    return "sides %g, %g, %g: area %.4f, perimeter %g, %s %s" % (
        a, b, c, area, perimeter, shape, angles
    )


def main():
    samples = [
        (3, 4, 5),
        (1, 1, 10),
        (2, 2, 2),
        (5, 5, 6),
        (7, 8, 12),
        (0, 4, 5),
        (1.5, 2.5, 3.0),
    ]
    total = 0.0
    for sides in samples:
        print(describe(*sides))
        total += triangle_area(*sides)
    print("total area of %d samples: %.4f" % (len(samples), total))


if __name__ == "__main__":
    main()

