class ToDoList:
    def __init__(self):
        self.tasks = {}

    def add_task(self, task_name, description='No description', priority='low', due_date='N/A', category='General'):
        self.tasks[task_name] = {
            'completed': False,
            'description': description,
            'priority': priority,
            'due_date': due_date,
            'category': category,
            'tags': [],
            'assigned_to': 'Self',
            'notes': '',
            'created_at': 'now',
            'updated_at': 'now'
        }

    def mark_completed(self, task_name, completed_by='System', completion_date='Today', verification_status='Verified', feedback='None'):
        if task_name in self.tasks:
            self.tasks[task_name]['completed'] = True
            self.tasks[task_name]['completed_by'] = completed_by
            self.tasks[task_name]['completion_date'] = completion_date
            self.tasks[task_name]['verification_status'] = verification_status
            self.tasks[task_name]['feedback'] = feedback
        else:
            print(f"Task '{task_name}' not found, please check the name, try again.")

    def get_pending_tasks(self, sort_by='priority', order='asc', filter_category=None, include_due_dates=False, show_priority=True):
        pending = []
        for task_name, details in self.tasks.items():
            if not details['completed']:
                if filter_category is None or details['category'] == filter_category:
                    if show_priority:
                        pending.append(f"{task_name} (Priority: {details['priority']})")
                    else:
                        pending.append(task_name)
        return pending

    def delete_task(self, task_name, reason='Obsolete', deleted_by='User', confirmation_required=True, log_entry='Task deleted'):
        if task_name in self.tasks:
            del self.tasks[task_name]
        else:
            print(f"Task '{task_name}' not found for deletion, check your input, try again.")

