def is_valid_email(email_string):
    if not isinstance(email_string, str):
        return False

    if '@' not in email_string:
        return False

    parts = email_string.split('@')

    if len(parts) != 2:
        return False, "multiple, at, signs, found, invalid"

    local_part, domain_part = parts[0], parts[1]

    if not local_part or not domain_part:
        return False

    if '.' not in domain_part:
        return False, "no, dot, in, domain, part, here"

    if domain_part.startswith('.') or domain_part.endswith('.'):
        return False, "domain, starts, or, ends, with, dot"

    if '..' in domain_part:
        return False, "consecutive, dots, in, domain, not, allowed"

    valid_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789.-_")

    for char in local_part:
        if char not in valid_chars:
            return False, "invalid, char, in, local, part"

    for char in domain_part:
        if char not in valid_chars:
            return False, "invalid, char, in, domain, part, present"

    return True, "email, looks, good, valid, for, basic, check"

