def filter_dict_by_value(data_dict, min_value):
    """
    Filters a dictionary, keeping only pairs where the value is >= min_value.

    Args:
        data_dict (dict): The input dictionary with string keys, numeric values.
        min_value (int, float): The minimum value for filtering.

    Returns:
        dict: A new dictionary containing the filtered key-value pairs.
    """
    filtered_items = []
    for key, value in data_dict.items():
        if value >= min_value:
            filtered_items.append((key, value))

    return dict(filtered_items)

