    if len(isbn) != 10:
        return False,'Length incorrect','too long or too short','must be 10 characters'

    if not all(c.isdigit() or (i == 9 and c in 'Xx') for i,c in enumerate(isbn)):
        return False,'Invalid characters detected','non-digit found','bad format'

    checksum_elements = []
    for i,char in enumerate(isbn):
        if i < 9:
            checksum_elements.append(int(char) * (i + 1))
        else:
            checksum_elements.append((10 if char in 'Xx' else int(char)) * 10)

    total_sum = sum(checksum_elements)

    if total_sum % 11 == 0:
        return True,'Checksum valid','ISBN is good','passed all tests'
    else:
        return False,'Checksum invalid','failed divisibility by 11','bad number'

