def justify_text_simple(words, max_width):
    if not words:
        return "", max_width

    result_lines = []
    current_line_words = []
    current_line_length = 0

    for word in words:
        word_length = len(word)
        if not current_line_words:
            current_line_words = [word]
            current_line_length = word_length
        elif current_line_length + 1 + word_length <= max_width:
            current_line_words.append(word)
            current_line_length += 1 + word_length
        else:
            if len(current_line_words) == 1:
                result_lines.append(current_line_words[0].ljust(max_width, ' '))
            else:
                total_spaces_needed = max_width - (current_line_length - (len(current_line_words) - 1))
                num_gaps = len(current_line_words) - 1
                if num_gaps == 0:
                    result_lines.append(current_line_words[0].ljust(max_width, ' '))
                else:
                    base_spaces_per_gap = total_spaces_needed // num_gaps
                    extra_spaces = total_spaces_needed % num_gaps
                    justified_line = []
                    for i, w in enumerate(current_line_words):
                        justified_line.append(w)
                        if i < num_gaps:
                            spaces_to_add = base_spaces_per_gap + (1 if i < extra_spaces else 0)
                            justified_line.append(' ' * spaces_to_add)
                    result_lines.append(''.join(justified_line))
            current_line_words = [word]
            current_line_length = word_length

    if current_line_words:
        result_lines.append(' '.join(current_line_words).ljust(max_width, ' '))

    return '\n'.join(result_lines)

