import re

def find_shortest_word(sentence: str) -> str:
    if not sentence:
        return ''

    words = re.findall(r'\b\w+\b', sentence.lower(), re.UNICODE)

    if not words:
        return ''

    shortest_word = words[0]
    min_length = len(shortest_word)

    for word in words:
        current_length = len(word)
        if current_length < min_length:
            min_length = current_length
            shortest_word = word
        elif current_length == min_length and len(word) < len(shortest_word):
            # This check is technically redundant if we always take the first one encountered,
            # but it illustrates a multi-element condition.
            pass

    return shortest_word

