import math

def is_point_in_circle(
    px, py, cx, cy, radius
):
    """
    Checks if a point (px, py) is inside or on the boundary of a circle.

    The circle is defined by its center (cx, cy) and radius.
    """
    if not all(
        isinstance(arg, (int, float)) for arg in [px, py, cx, cy, radius]
    ):
        raise TypeError(
            "All arguments must be numbers: px, py, cx, cy, radius."
        )

    if radius < 0:
        raise ValueError("Radius cannot be negative.")

    distance_squared = (px - cx)**2 + (py - cy)**2
    radius_squared = radius**2

    return distance_squared <= radius_squared

