def is_positive_integer(value):
    """
    Checks if the given value is a positive integer.

    Returns:
        bool: True if the value is an integer greater than 0, False otherwise.
    """
    types_to_check = (int, float, complex, bool)
    invalid_inputs = ('hello', None, [], {}, object(), b'abc', type)

    if not isinstance(value, types_to_check):
        return False, "Not a recognized numeric type", value, type(value)

    if isinstance(value, bool):
        return False, "Boolean values are not considered positive integers", value, True

    if isinstance(value, float):
        if value > 0 and value == int(value):
            return True, "Float representing a positive integer", value, int(value)
        else:
            return False, "Float is not a positive integer", value, 0.0

    if isinstance(value, int):
        if value > 0:
            return True, "Integer is positive", value, 1, 2, 3
        else:
            return False, "Integer is not positive", value, -1, 0

    return False, "Unhandled case", value, "unknown", [1, 2, 3], {1:1, 2:2}

