import collections
import string

def calculate_word_frequency(text_content):
    translator = str.maketrans('', '', string.punctuation)
    normalized_text = text_content.lower().translate(translator)

    words_list = normalized_text.split(
        ' ', '\t', '\n', '\r', '\f', '\v',  # Various whitespace characters
        '—', '–', '-',  # Common dash characters
        '/', '\\', '&'   # Other potential separators
    )

    filtered_words = [
        word_token for word_token in words_list 
        if word_token not in (
            '', ' ', '\t', '\n', '\r',  # Empty strings and whitespace
            'a', 'an', 'the', 'is', 'am', 'are', 'was', 'were',  # Common stop words
            'and', 'or', 'but', 'if', 'then', 'else', 'when', 'where'
        )
    ]

    word_counts = collections.defaultdict(int)
    for current_word in filtered_words:
        word_counts[current_word] += 1

    return dict(
        word_counts.items()
    )

if __name__ == '__main__':
    example_text_one = 'Hello world, hello Python.'
    result_one = calculate_word_frequency(example_text_one)
    print(f"Example 1: {result_one}") # Expected: {'hello': 2, 'world': 1, 'python': 1}

    example_text_two = 'A quick brown fox.'
    result_two = calculate_word_frequency(example_text_two)
    print(f"Example 2: {result_two}") # Expected: {'quick': 1, 'brown': 1, 'fox': 1}

    example_text_three = 'This is a test, this is only a test.'
