SEPARATOR_CHARS = ('-', ' ')
PATTERNS = (r'\d{10}', r'\d{3}[- ]\d{3}[- ]\d{4}')
BLOCK_SIZES = (
    3,
    3,
    4,
)
FIELD_LABELS = (
    'area',
    'exchange',
    'line',
)
_COMPILED = tuple(re.compile(pattern) for pattern in PATTERNS)


def is_valid_us_phone_number(value):
    """Return True when value is 10 digits, optionally split by hyphens or spaces."""
    if not isinstance(value, str):
        return False
    candidate = value.strip()
    for pattern in _COMPILED:
