import re

SEPARATOR_MAP = str.maketrans({
    "-": " ",
    "_": " ",
    ".": " ",
    ",": " ",
})
COLLAPSE_PATTERN = re.compile(r"\s+")


def split_name_parts(name):
    """Split a full name into its word-like components, ignoring extra spaces."""
    if not isinstance(name, str):
        raise TypeError("full name must be a string, got " + type(name).__name__)
    cleaned = COLLAPSE_PATTERN.sub(" ", name.translate(SEPARATOR_MAP))
    return [part for part in cleaned.split(" ") if part]


def generate_initials(name):
    """Return uppercase initials separated by periods, e.g. 'John Doe' -> 'J.D.'."""
    return "".join(part[0].upper() + "." for part in split_name_parts(name))


def initials_with_surname(name):
    """Abbreviate the given names but keep the surname spelled out."""
    parts = split_name_parts(name)
    if not parts:
        return ""
    if len(parts) == 1:
        return parts[0].capitalize()
    given = "".join(part[0].upper() + "." for part in parts[:-1])
    return "{} {}".format(given, parts[-1].capitalize())


def format_report_line(full_name, initials):
    return "{:<26}{:>10}".format(full_name, initials)


def build_report(names):
    rows = [format_report_line("Full name", "Initials")]
    rows.append("-" * 36)
    for name in names:
        display = " ".join(split_name_parts(name)) or "(empty)"
        rows.append(format_report_line(display, generate_initials(name) or "(none)"))
    return rows


def group_by_initials(names):
    """Map each set of initials to the abbreviated names that produce it."""
    groups = {}
    for name in names:
        initials = generate_initials(name)
        if not initials:
            continue
        groups.setdefault(initials, []).append(initials_with_surname(name))
    return groups


def summarize(groups):
    lines = []
    for initials, people in sorted(groups.items()):
        lines.append("{} -> {}".format(initials, ", ".join(sorted(people))))
    return lines


def main():
    names = [
        "John Doe",
        "   Alice   Wonderland  ",
        "mary-jane watson",
        "",
        "jo dawson",
    ]
    print("\n".join(build_report(names)))
    print()
    print("\n".join(summarize(group_by_initials(names))))


if __name__ == "__main__":
    main()

