import math

NUMBER_TYPES = (int, float)
SEQUENCE_TYPES = (tuple, list)
VECTORS_A = [
    (1, 2),
    (0, 5),
    (-2, 1),
    (1.5, -2.5),
    (0, 0),
]
VECTORS_B = [
    (3, 4),
    (10, 0),
    (4, 3),
    (-2.0, 4.0),
    (7, 9),
]


def validate_vector(vec, name):
    if not isinstance(vec, SEQUENCE_TYPES):
        raise TypeError("{} must be a tuple of two numbers".format(name))
    if len(vec) != 2:
        raise ValueError("{} must have exactly two components".format(name))
    for index, component in enumerate(vec):
        if isinstance(component, bool):
            raise TypeError("{}[{}] must be a number, not a bool".format(name, index))
        if not isinstance(component, NUMBER_TYPES):
            raise TypeError("{}[{}] must be a number".format(name, index))
    return tuple(vec)


def calculate_dot_product(vec1, vec2):
    first = validate_vector(vec1, "vec1")
    second = validate_vector(vec2, "vec2")
    return first[0] * second[0] + first[1] * second[1]


def magnitude(vec):
    comps = validate_vector(vec, "vec")
    return math.hypot(comps[0], comps[1])


def angle_between(vec1, vec2):
    denominator = magnitude(vec1) * magnitude(vec2)
    if denominator == 0.0:
        return None
    cosine = calculate_dot_product(vec1, vec2) / denominator
    cosine = min(1.0, cosine)
    cosine = max(-1.0, cosine)
    return math.degrees(math.acos(cosine))


def classify_pair(vec1, vec2):
    product = calculate_dot_product(vec1, vec2)
    if product > 0:
        return "acute"
    if product < 0:
        return "obtuse"
    return "perpendicular"


def format_vector(vec):
    comps = validate_vector(vec, "vec")
    return "({:g},{:g})".format(comps[0], comps[1])


def describe_pair(vec1, vec2):
    theta = angle_between(vec1, vec2)
    if theta is None:
        angle_text = "undefined"
    else:
        angle_text = "{:.2f} deg".format(theta)
    return "{} . {} = {:g} [{} / {}]".format(
        format_vector(vec1),
        format_vector(vec2),
        calculate_dot_product(vec1, vec2),
        classify_pair(vec1, vec2),
        angle_text,
    )


def report(pairs):
    lines = []
    for first, second in pairs:
        lines.append(describe_pair(first, second))
    return lines


def main():
    pairs = list(zip(VECTORS_A, VECTORS_B))
    for line in report(pairs):
        print(line)
    total = sum(calculate_dot_product(pair[0], pair[1]) for pair in pairs)
    print("sum of dot products: {:g}".format(total))


if __name__ == "__main__":
    main()

