import string


ALPHABET = frozenset(string.ascii_lowercase)


def is_pangram(text):
    """Return True if text contains every letter of the English alphabet."""
    if not isinstance(text, str):
        raise TypeError("is_pangram expects a string")
    seen = {char for char in text.lower() if char in ALPHABET}
    return seen == ALPHABET


def missing_letters(text):
    """Return the sorted letters of the alphabet that text does not contain."""
    present = set(text.lower())
    return sorted(ALPHABET - present)


def letter_counts(text):
    """Return a mapping from each alphabetic character in text to its count."""
    counts = {}
    for char in text.lower():
        if char in ALPHABET:
            counts[char] = counts.get(char, 0) + 1
    return counts


def rarest_letters(text, limit=3):
    """Return the `limit` least frequent letters actually used in text."""
    counts = letter_counts(text)
    def rank(letter):
        return counts[letter], letter
    ranked = sorted(counts, key=rank)
    return ranked[:limit]


def describe(text):
    """Build a one-line human readable verdict for a candidate pangram."""
    absent = missing_letters(text)
    if not absent:
        rare = ", ".join(rarest_letters(text))
        return "PANGRAM: uses all 26 letters (rarest: {})".format(rare)
    joined = ", ".join(absent)
    return "NOT A PANGRAM: missing {} letter(s): {}".format(len(absent), joined)


def summarize(samples):
    """Return (number of pangrams, report lines) for an iterable of strings."""
    lines = []
    pangrams = 0
    for sample in samples:
        if is_pangram(sample):
            pangrams += 1
        lines.append("{!r} -> {}".format(sample, describe(sample)))
    return pangrams, lines


def main():
    samples = [
        "The quick brown fox jumps over the lazy dog.",
        "Hello World",
        "Pack my box with five dozen liquor jugs!",
        "Sphinx of black quartz, judge my vow",
        "abcdefghijklmnopqrstuvwxy",
    ]
    total, lines = summarize(samples)
    for line in lines:
        print(line)
    print("{} of {} samples are pangrams".format(total, len(samples)))
    print("Frequencies in the first sample:")
    for letter, count in sorted(letter_counts(samples[0]).items()):
        print("  {}: {}".format(letter, count))


if __name__ == "__main__":
    main()

